(window.__BOOKS=window.__BOOKS||{})["e_troades"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Посейдон</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Афина</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"gekuba\">Гекуба</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Хор троянских пленниц</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"kassandra\">Кассандра</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"andromaha\">Андромаха</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"menelay\">Менелай</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"elena\">Елена</span></span> <span class=\"act-no\">(III)</span>"],["place","Действие происходит в ахейском стане после разрушения Трои. У шатра распростертая на земле Гекуба"],["act","Пролог","a1",""],["scene","Явление первое","s1",1,1],["sp","Посейдон"],["v","Соленую Эгейскую пучину",0,1,0,0],["v","Покинул я, где хоры Нереид,",0,1,0,0],["v","Свиваяся следами, дивно блещут…",0,2,0,0],["v","О, никогда с тех пор, как с Фебом мы",0,3,0,0],["v","Вокруг земли Троянской по отвесу",0,4,0,0],["v","Расставили твердыни камней, нет,",0,5,0,0],["v","На миг с тех пор благая мысль о Трое",0,6,0,0],["v","Не покидала сердца, а теперь",0,7,0,0],["v","Что Троя? дым да тяжкие следы",0,8,0,0],["v","Аргосского копья.",0,9,0,0],["v","По замыслу Паллады, муж парнасский<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,10,0,1],["v","Из дерева коня им смастерил",0,10,0,0],["v","И ратными наполнил; этот дар",0,11,0,0],["v","Погибельный троянцами был принят.",0,12,0,0],["v","Так и в века пойдет «копейный конь»,",0,13,0,0],["v","Что копья им во чреве сохранил он.",0,13,0,0],["v","Безлюдны рощи наши, и вокруг",0,14,0,0],["v","Убийство нам чертоги обагрило.",0,15,0,0],["v","Великий царь и тот близ алтаря,",0,16,0,0],["v","Хранителя оград, лежит, настигнут.",0,16,0,0],["v","А золота, доспехов-то из Трои",0,17,0,0],["v","На корабли что греки носят. Им",0,18,0,0],["v","Лишь ветер бы теперь попутный. Семьи",0,19,0,0],["v","Там заждались их: шутка — десять лет",0,20,0,1],["v","В родной земле посева не встречали.",0,20,0,0],["v","Приходится и мне отсюда. Сам",0,21,0,0],["v","Афиною и Герой я осилен,",0,22,0,0],["v","Как и мои фригийцы. Покидаю",0,23,0,0],["v","И славу стен, и прелесть алтарей.",0,24,0,0],["v","Ведь и богов тот ужас запустенья,",0,25,0,0],["v","Та язва не щадит. До них ли людям…",0,26,0,0],["v","Когда гудят от стонов берега",0,27,0,0],["v","Троянских рек, ахейцы ж женщин делят?",0,28,0,0],["v","Да, жребий их уж вынут. И одни",0,29,0,0],["v","Аркадянам достались, а другим",0,30,0,1],["v","В Фессалию дорога. Не без дела",0,30,0,0],["v","Остались и в Афинах Тесеиды.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,31,0,0],["v","Ушедшие от жребия вон там",0,32,0,0],["v","Под сению томятся, для вождей",0,33,0,0],["v","Назначены, — меж ними и <span class=\"ch\" data-ch=\"elena\">Елена</span>,",0,33,0,0],["v","Тиндара дочь, спартанка, и закон",0,34,0,0],["v","От пленницы ее не отличает.",0,35,0,0],["v","А близ ворот несчастную жену",0,36,0,0],["v","Гекубу, кто захочет, видит: вот",0,36,0,0],["v","Она в слезах обильных… да и ей ли",0,37,0,0],["v","Не исходить слезами? Втихомолку",0,38,0,0],["v","Злодейски дочь убита Поликсена<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,39,0,0],["v","Над насыпью Ахилловой могилы.",0,40,0,1],["v","А где Приам? Где дети? Если царь",0,40,0,0],["v","Сам Аполлон из бешеного бега",0,41,0,0],["v","Девицею <span class=\"ch\" data-ch=\"kassandra\">Кассандру</span> отпустил,",0,42,0,0],["v","То ложе ей, презрев закон и бога,",0,42,0,0],["v","Осквернено девичье ей Атридом",0,43,0,0],["v","Насильно и во мраке. Но, прости,",0,44,0,0],["v","О Илион, блаженный град когда-то!",0,45,0,0],["v","О, главная твердыня, до сих пор",0,45,0,0],["v","Ты высилась бы, если б не Паллада,",0,46,0,0],["v","Кронида дочь: она тебя сгубила.",0,47,0,0],["scene","Явление второе","s2",1,2],["v","Появляется Афина Паллада.",0,47,0,0],["sp","Афина"],["v","Дозволишь ли, ближайший к Зевсу бог,",0,48,0,0],["v","Великий бог, чтобы к тебе я слово,",0,49,0,0],["v","Забыв вражду, с приветом обратила?",0,50,0,1],["sp","Посейдон"],["v","Владычица Афина, чары сердцу",0,51,0,0],["v","В беседе меж родными… Говори.",0,52,0,0],["sp","Афина"],["v","Хвалю я мир души твоей. А дело",0,53,0,0],["v","Коснется нас обоих, Посейдон.",0,54,0,0],["sp","Посейдон"],["v","Но чья же весть? Иль от кого из дивных?",0,55,0,0],["v","Не Зевсова ль? Или кого ль еще?",0,56,0,0],["sp","Афина"],["v","Недалеко искать: о Трое речь.",0,57,0,0],["v","Из-за нее ищу в тебе опоры.",0,58,0,0],["sp","Посейдон"],["v","Иль, прежний гнев покинув, ты теперь",0,59,0,0],["v","Ее, в огне истлевшей, пожалела?",0,60,0,1],["sp","Афина"],["v","Скажи сперва: коль я открою план,",0,60,0,0],["v","Ты мне помочь в желанном согласишься ль?",0,61,0,0],["sp","Посейдон"],["v","Конечно да. Но знать и я хочу:",0,62,0,0],["v","Ты с кем теперь: с ахейцем иль фригийцем?",0,63,0,0],["sp","Афина"],["v","Обрадовать троянцев и возврат",0,64,0,0],["v","Хотела б я ахейцев сделать горьким.",0,65,0,0],["sp","Посейдон"],["v","Но поворот такой я не пойму:",0,66,0,0],["v","За что же друг тебе стал ненавистен?",0,67,0,0],["sp","Афина"],["v","Иль не слыхал ты, бог, что надо мной",0,68,0,0],["v","И над моей святыней насмеялись?",0,69,0,0],["sp","Посейдон"],["v","Аякс когда <span class=\"ch\" data-ch=\"kassandra\">Кассандру</span> волочил?..",0,70,0,1],["sp","Афина"],["v","А эллины глядели — и ни слова.<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,70,0,0],["sp","Посейдон"],["v","Но не твоей ли силой Трою взяли?",0,71,0,0],["sp","Афина"],["v","Твоей теперь я эллинов казню.",0,72,0,0],["sp","Посейдон"],["v","Что ж, я готов. Но что проделать хочешь?",0,73,0,0],["sp","Афина"],["v","Чтоб их возврат был злой возврат, хочу.",0,74,0,0],["sp","Посейдон"],["v","На суше ль здесь иль на соленой влаге?",0,75,0,0],["sp","Афина"],["v","Едва домой из Трои корабли",0,76,0,0],["v","Направятся, и дождь и град на них",0,77,0,0],["v","Безмерные посыплются, и неба",0,78,0,0],["v","Им черное пошлет Кронид дыханье,",0,79,0,0],["v","А мне перун вручит, и, поразив",0,80,0,1],["v","Ахейские суда, испепелю их…",0,80,0,0],["v","Ты ж, бог, заставь Эгейские пути",0,81,0,0],["v","Греметь от треволнений и в пучину",0,82,0,0],["v","Открой водовороты да наполни",0,83,0,0],["v","Их трупами земли Евбейской: пусть",0,84,0,0],["v","Научатся мои чертоги чтить,",0,85,0,0],["v","Да и других бессмертных не порочить.",0,85,0,0],["sp","Посейдон"],["v","Да будет так. Услуга эта слов",0,86,0,0],["v","Не требует обильных. Растревожу",0,87,0,0],["v","Я зыбь пучин Эгейских. А коса",0,88,0,0],["v","Миконская, делосские утесы,",0,89,0,0],["v","И Лемн, и Скир, и Кафарейский мыс",0,90,0,1],["v","Все трупами усеются. Ступай.",0,90,0,0],["v","Из отчих рук приявши на Олимпе<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,91,0,0],["v","Его перун, ты жди, чтобы канат",0,92,0,0],["v","На эллинских судах был отдан, дева.",0,93,0,0],["v","Не слеп ли меж людей, кто рушил город,<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,94,0,0],["v","И храмы и могилы, честь умерших?",0,95,0,0],["v","Предавши их опустошенью, он",0,95,0,0],["v","Хоть позже, сам за это погибает.",0,96,0,0],["v","Посейдон и Афина исчезают.",0,97,0,0],["scene","Явление третье","s3",1,3],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О злосчастная, встань! Головой и земли",0,98,0,0],["v","Не томи. Не твоя и земля.",0,99,0,0],["v","Царства нашего нет.",0,100,0,1],["sd","(Приподнимается.)"],["v","Демон сменился, а ты крепись,",0,101,0,0],["v","Ты по волне плыви, ты за судьбу держись.",0,102,0,0],["v","Жизни нельзя вперерез идти,",0,103,0,0],["v","Против волны тебе нет пути.",0,104,0,0],["v","Горе, о горе!",0,105,4,0],["v","Только без слез обратиться к чему ж?",0,106,0,0],["v","Если ушла и отчизна, и дети, и муж,",0,107,0,0],["v","Если, трудами отцов нажито,",0,108,0,0],["v","Гордое счастье и то оказалось ничто…",0,109,0,0],["v","Так о чем же молчать и о чем не молчать?",0,110,0,1],["v","И о чем только плакать?",0,111,0,0],["v","О, как твердо оно, это ложе,",0,112,0,0],["v","И как тело согнутое ноет мое,",0,113,0,0],["v","Голова, и виски, и бока,",0,114,0,0],["v","Как со стоном покоя ищу я спине,",0,115,0,0],["v","С боку на бок ворочаюсь тяжко.",0,116,0,0],["v","Но утеха и скорбному есть.",0,117,0,0],["v","Это Муза с унылым стенаньем.",0,120,0,1],["str","Строфа"],["v","Увы, о ладьи Эллады,",0,121,0,0],["v","О, зачем вы, ладьи, на веслах",0,122,0,0],["v","По пурпурному морю бежали",0,123,0,0],["v","Из заводей тихих",0,124,2,0],["v","И у Трои зачем священной",0,125,2,0],["v","Искусством Египта",0,126,0,0],["v","Канаты свитые кидали,",0,127,2,0],["v","И пеан звучал ненавистный",0,128,0,0],["v","В сладкой музыке флейт и свирелей…",0,129,0,0],["v","Не за той ли, проклятой, вы мчались, ладьи,",0,130,0,1],["v","Что была <span class=\"ch\" data-ch=\"menelay\">Менелаю</span> женою,",0,130,0,0],["v","И позором для Кастора-брата,",0,131,0,0],["v","И бесславьем родимой ⟨земли⟩,",0,132,0,0],["v","Не за той ли ⟨женой⟩, что убийцей была",0,133,0,0],["v","Для Приама, со мной пятьдесят",0,134,0,0],["v","Подъявшего славных детей,",0,135,0,0],["v","Что <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span> прибила ладью",0,136,0,0],["v","К этим бедам?..",0,137,0,0],["str","Антистрофа"],["v","Увы! Куда ж я пришла сидеть?",0,138,0,0],["v","Шатер сторожить Агамемнону?",0,139,0,0],["v","Рабыней меня из дворца вели,",0,140,0,1],["v","Старуху, печально обритую,",0,140,0,0],["v","Горько!",0,141,2,0],["v","Гей, вы, меднокопейщиков",0,142,0,0],["v","Горькие жены… Девушки,",0,143,0,0],["v","Трои краса злоневестная,",0,143,0,0],["v","Троя курится священная,",0,144,0,0],["v","Троя дымится… восплачемте!",0,145,0,0],["v","Я, точно птица птенцов своих,",0,146,0,0],["v","Жалобе вас обучу сейчас.",0,146,0,0],["v","Новая песня — не та, увы,",0,147,0,0],["v","Что запевала когда-то я,",0,148,0,0],["v","Славя небесных и к пляске вас",0,149,0,0],["v","Голосом звала, Приамовой",0,150,0,1],["v","Гордая силой… О, горе мне…",0,151,0,0],["scene","Явление четвертое","s4",1,4],["scene","Вступительная песнь хора","s5",1,5],["v","Из шатра выходит первое полухорие.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,152,0,0],["sp","Корифей первого полухория"],["str","Строфа I"],["v","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>? что стонешь? о чем говоришь?",0,153,2,0],["v","Темна твоя речь. В шатер к нам проник",0,154,0,0],["v","Твой жалобный крик, твой грустный напев,",0,155,0,0],["v","И ужас объял нас, троянок,",0,156,2,0],["v","Нас, которые здесь",0,157,2,0],["v","Над жребием плачутся рабским.",0,158,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дети! Ахейцы готовят возврат.",0,159,0,0],["v","Гребцы хлопочут у весел.",0,160,2,1],["sp","Корифей первого полухория"],["v","Что слышу? меня повлекут",0,160,0,0],["v","На муку с родных побережий?",0,161,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не знаю, но чую беду.",0,162,0,0],["sp","Корифей первого полухория"],["v","Увы мне!",0,163,3,0],["v","Троянки, несчастные девы,",0,164,2,0],["v","Из шатров выбирайтесь. Аргосцы",0,165,0,0],["v","Готовят ладьи…",0,166,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ах! Ах!",0,167,2,0],["v","Кассандру, смотрите, не звать,",0,168,0,0],["v","Деву, полную Вакха,",0,169,2,0],["v","На глумленье аргосцам,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,170,2,0],["v","Мне на новое горе…",0,171,2,0],["v","Троя, погибшая Троя!",0,172,2,0],["v","О, горькая участь — расстаться с тобой,",0,173,0,0],["v","Живым или мертвым!",0,174,2,0],["v","Из шатра выходит второе полухорие.",0,175,0,0],["sp","Корифей второго полухория"],["str","Антистрофа I"],["v","Увы мне! Дрожа, я покинула сень",0,176,0,0],["v","Атрида… Скажи, царица, скажи,",0,177,0,0],["v","Скажи мне: убить меня собрались",0,178,0,0],["v","Аргосцы — иль там мореходы",0,179,2,0],["v","Весла спешно берут,",0,180,2,1],["v","Ладьи — тюрьму нашу — ладят?",0,180,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дочь моя! Крылья смелее расправь,",0,181,0,0],["v","Что страх и ужас зажали…",0,182,2,0],["sp","Корифей второго полухория"],["v","А весть та из войска придет,",0,183,0,0],["v","Кому я достанусь рабою?",0,184,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Твой жребий, дитя, недалек.",0,185,0,0],["sp","Корифей второго полухория"],["v","Увы мне!",0,185,2,0],["v","На нивы ль Ахайи, во Фгию ль,",0,186,0,0],["v","Иль на остров какой средь пучины<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,187,0,0],["v","Меня увезут?",0,188,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ах! Ах!",0,189,2,0],["v","А я в услуженье кому,",0,190,2,1],["v","Трутень старый, достанусь,",0,191,2,0],["v","Точно труп или призрак,",0,192,2,0],["v","Тень, которая гаснет?",0,193,2,0],["v","Буду ли дом караулить",0,194,2,0],["v","Иль нянькою в доме малюток качать",0,195,0,0],["v","Я, Трои царица?",0,196,2,0],["sp","Хор"],["str","Строфа II"],["v","О, увы мне! слезных слов",0,197,0,0],["v","О твоем бесславии стоны!",0,198,0,0],["v","Мне близ Иды больше полотен",0,199,0,0],["v","Не украсить тканым узором,",0,200,0,1],["v","И телам детей я последний,",0,201,0,0],["v","Я последний луч посылаю.",0,202,0,0],["v","Я тяжеле подъемлю муки,",0,203,0,0],["v","Буду этому стлать я ложе, —",0,204,0,0],["v","О проклятая ночь, о демон! —<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,205,0,0],["v","Иль в Пирене священную влагу,",0,206,0,0],["v","Как раба печальная, черпать…",0,207,0,0],["v","Если б славные, если б достались мне",0,208,0,0],["v","Нивы Тесея блаженные,",0,209,0,0],["v","Лишь не Еврота мне водовороты бы,",0,210,0,1],["v","Не ненавистные сени Еленины,",0,211,0,0],["v","И <span class=\"ch\" data-ch=\"menelay\">Менелаю</span> бы, Трои рушителю,",0,212,0,0],["v","Не попадалась я горькой рабыней!",0,213,0,0],["str","Антистрофа II"],["v","Я узнала, что есть святой",0,214,0,0],["v","У подножья Олимпа блаженного",0,215,0,0],["v","Край Пенея тучнополянный.<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,216,0,0],["v","Если нет на нивы Тесея",0,217,0,0],["v","Мне пути, я туда б желала.",0,218,0,0],["v","О полях Гефеста близ Этны,<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,220,0,1],["v","И оттуда видать Финику.",0,220,0,0],["v","Есть молва, что ту землю, матерь",0,221,0,0],["v","Сицилийских вершин, венцами",0,222,0,0],["v","Отмечают на играх за доблесть;",0,223,0,0],["v","Мне и там судьбина завидней.",0,224,0,0],["v","Есть и еще земля, близ Ионийского<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,225,0,0],["v","Моря лежит она, Кратисом",0,225,0,0],["v","Орошена она, и золотятся в ней",0,226,0,0],["v","Локоны светлые, поят священные",0,227,0,0],["v","Воды источников нивы и области",0,228,0,0],["v","Храбрых воителей. Ту я люблю страну.",0,229,0,0],["sp","Корифей"],["v","Но вот уже, вот от Ахейи посол;",0,230,0,1],["v","Решенье несет он из стана.",0,230,2,0],["v","Шаги его быстры… Они все быстрей.",0,231,0,0],["v","Что скажет? Увы нам!.. Теперь мы навек",0,232,0,0],["v","Рабыни земли Дорийской.",0,233,2,0],["act","Действие первое","a2","I"],["scene","Явление пятое","s6",2,6],["sd","Входит <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>."],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Гекуба, к вам дорогу проторил",0,234,0,0],["v","Я в Илион. Тебе посол ахейский",0,235,0,0],["v","Себя едва ли должен называть.",0,236,0,0],["v","Но в этот раз <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span> с новизною.",0,237,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Вот оно, вот оно, дети:",0,238,0,0],["v","Чуяло сердце.",0,239,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Коль вы того боялись — жребий вынут.",0,240,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Куда, скажи мне, куда —",0,240,0,0],["v","В Фессалию, в город ли Фтии,",0,241,0,0],["v","На Кадмовы ль нивы пути нам?",0,242,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Не вместе вас, а порознь разберут…",0,243,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Так кто же достался кому,",0,244,0,0],["v","И кого из троянок",0,245,0,0],["v","Ждет жребий счастливый?",0,245,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Все знаю, все, но разделяй вопросы.",0,246,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Моя несчастная дочь",0,247,0,0],["v","<span class=\"ch\" data-ch=\"kassandra\">Кассандра</span> за кем?",0,248,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Избранницу ведет Агамемнон.",0,249,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Рабыней спартанской невестке —<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,250,0,1],["v","Увы мне, увы мне!",0,251,1,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Нет, не совсем. Наложницею тайной.",0,252,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Она, которой Аполлон",0,253,0,0],["v","Оставил ложе чистым, златокудрый?",0,254,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Да, ранен царь любовью к деве дивной.",0,255,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ключи Аполлона забрось!",0,256,0,0],["v","Повязки священные бога",0,257,0,0],["v","Сорви с головы злосчастной!",0,258,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Иль быть царю утехой — жребий плох?",0,259,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","А та, птенец мой, что только что отняли вы?",0,260,0,1],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","О ком вопрос? О Поликсене, что ли?",0,260,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","С кем ее жребий сдружил?",0,261,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Приставлена к Ахиллову кургану.",0,262,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дитя мое, родила тебя я прислугою",0,263,0,0],["v","Надмогильною. Но скажи, мой друг:",0,264,1,0],["v","Иль у эллинов есть закон такой,",0,265,1,0],["v","Иль обычай есть?",0,266,3,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","На благо ей. Прославь дочерний жребий.",0,267,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Как мне понять тебя?<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,268,0,0],["v","Дочь-то жива моя?",0,269,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","От всяких бед судьба ее хранит.",0,270,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","А <span class=\"ch\" data-ch=\"andromaha\">Андромаху</span>, друг, медью блиставшего?",0,271,0,0],["v","Некогда Гектора, кто же жену возьмет?",0,272,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Ее себе назначил сын Ахилла.",0,273,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ну, а я, раба престарелая,",0,274,0,0],["v","Чья же буду я с костылем моим —",0,275,0,0],["v","И на трех ногах, да нестойкая?",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","При дележе пришлась ты Одиссею.",0,277,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы, увы!",0,278,2,0],["v","Бритую голову бей, терзай!",0,279,0,0],["v","Щеки царапай… О, горе мне!",0,280,0,1],["v","Жребий меня лукавому",0,281,2,0],["v","Отдал в неволю зловерному:",0,282,2,0],["v","Права не знает он, бог не страшит его,",0,283,0,0],["v","Змей подколодный он, гневом согласие",0,284,0,0],["v","Царь Одиссей творит, сума переметная.",0,285,0,0],["v","Пожалейте ж меня вы, жены:",0,286,2,0],["v","Я погибла, и горшей доли",0,290,2,1],["v","Ни одной не выбросил случай.<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,291,2,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Ступайте же, прислужницы, доставьте",0,294,0,1],["v","<span class=\"ch\" data-ch=\"kassandra\">Кассандру</span> нам скорее, чтоб, вождю",0,294,0,0],["v","Ее вручив, я мог бы и другим",0,295,0,0],["v","Распределить по господам их пленниц.",0,296,0,0],["sd","(Смотрит на шатер.)"],["v","Ба… ба… А это что же там в палатках",0,297,0,0],["v","Курится и трещит? Да это факел?",0,298,0,0],["v","Что делают троянки? Иль пожаром",0,299,0,0],["v","Задумали от Аргоса спастись,",0,300,0,1],["v","Куда им путь назначен? Иль себя",0,300,0,0],["v","Решили сжечь в безумье жадном смерти?",0,301,0,0],["v","Что говорить! Свободным не легко",0,302,0,0],["v","Такой беды ярмо. Гей! Отопритесь!",0,302,0,0],["v","Желанное рабыням для господ",0,303,0,0],["v","Покажется, пожалуй, неугодным;",0,304,0,0],["v","А скажут — кто ж? <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span> виноват.",0,305,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не то, посол. Там вовсе нет пожара.",0,305,0,0],["v","Но, бешенством охвачена, сюда",0,306,0,0],["v","Кассандра, дочь моя, идет, я слышу.",0,307,0,0],["scene","Явление шестое","s7",2,7],["v","Входит <span class=\"ch\" data-ch=\"kassandra\">Кассандра</span> с горящим факелом.",0,307,0,0],["sp","<span class=\"ch\" data-ch=\"kassandra\">Кассандра</span>"],["str","Строфа"],["v","Встаньте! Места мне! Свету дай!",0,308,0,0],["v","С мольбой зажгу",0,309,2,0],["v","Факелы в храмине…<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,310,2,1],["v","Гляди, гляди",0,311,2,0],["v","На жениха. Как сияет он!",0,312,1,0],["v","В Аргос для ложа царева я",0,313,1,0],["v","Еду, невеста блаженная…",0,314,1,0],["v","О Гименей, о Гименей, о царь,",0,315,0,0],["v","Если ты, мать, за слезами не можешь, —<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,316,0,0],["v","Стоны о мертвом отце,",0,317,1,0],["v","О милой отчизне мешают.",0,318,1,0],["v","Я уж сама для свадьбы!",0,319,1,0],["v","Огонь запалю, родная!",0,320,1,1],["sd","(Машет факелом.)"],["v","Для солнца, для блеска",0,320,2,0],["v","Тебе, Гименей, огонь,",0,321,2,0],["v","Тебе, Геката пламенная,",0,322,2,0],["v","У девичьей постели —",0,323,2,0],["v","Так бог велит, так бог велит.",0,324,0,0],["str","Антистрофа"],["v","Выше! вверх посох! хор, веди:",0,325,0,0],["v","Эван, эвой!",0,325,2,0],["v","Как при отце моем:",0,326,2,0],["v","Ио! ио!",0,327,2,0],["v","В лучшие дни илионские",0,328,1,0],["v","Свят хоровод наш, я в Фебовом",0,329,1,0],["v","Храме курю лавровенчанном.",0,330,1,1],["v","О Гименей, о Гименей, о бог…",0,330,0,0],["sd","(Подходит к <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span>.)"],["v","Вместе ты стань, поднявшися на ноги,",0,331,0,0],["v","Пляску со мной разделять,",0,332,1,0],["v","Стопами драгами ступая.",0,333,1,0],["v","Зовите со мной, о жены,",0,334,2,0],["v","Блаженным напевом бога",0,335,2,0],["v","И кликом певиц…",0,336,3,0],["v","Воспойте, девы Фригии,",0,337,2,0],["v","Воспойте брак веселый мой",0,338,2,0],["v","И мне обетованный!",0,339,2,0],["v","Да славится, да славится!",0,340,0,1],["sp","Корифей"],["v","Объятую безумием схвати:",0,340,0,0],["v","Не дай ногам увлечь ее к солдатам.",0,341,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Гефест, о бог! Венчальный факел твой",0,342,0,0],["v","Нас веселит. Но этот блеск печален,",0,343,0,0],["v","И нет за ним надежды. О дитя,",0,344,0,0],["v","Не думала твою справлять я свадьбу",0,345,0,0],["v","Среди солдат и под угрозой, дочь,",0,345,0,0],["v","Аргосского копья. Отдай мне факел.",0,346,0,0],["v","Его неровно держишь, как менада,",0,347,0,0],["v","Кидаешься безумно, а душа",0,348,0,0],["v","Твоя найти не может мира. Право,",0,349,0,0],["v","Вокруг тебя все то же. Вы, троянки,",0,350,0,1],["v","Возьмите от нее огонь и песнь",0,350,0,0],["v","Венчальную ответствуйте слезами.",0,351,0,0],["sp","<span class=\"ch\" data-ch=\"kassandra\">Кассандра</span>"],["v","Победа, мать! Не радуешься ты",0,352,0,0],["v","На этот брак с царями! Ты украсить",0,353,0,0],["v","Мне головы не хочешь? Не должна ль ты",0,354,0,0],["v","Сама вести, толкать меня, что здесь я",0,355,0,0],["v","Замешкалась? Ведь если Локсий — бог,<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,356,0,0],["v","Так славный царь ахейцев Агамемнон",0,357,0,0],["v","Жену себе берет. Куда <span class=\"ch\" data-ch=\"elena\">Елена</span>!..",0,358,0,0],["v","Я уложу царя. Его дворец",0,359,0,0],["v","Я разорю в отплату за убитых",0,360,0,1],["v","Твоих детей и мужа. Но пока —",0,360,0,0],["v","Молчание… До времени из песни",0,361,0,0],["v","Мы выключим топор, что упадет",0,362,0,0],["v","На позвонок вот этот и еще",0,362,0,0],["v","Одну наметит шею… Но завеса",0,363,0,0],["v","На этот брак и матереубийство,",0,364,0,0],["v","Которое влечет он, и на гибель",0,364,0,0],["v","Атреева их корня. Илион!",0,365,0,0],["v","Я докажу, что ты блаженней греков.",0,366,0,0],["v","Мать думает, что я беснуюсь, — нет!..",0,366,0,0],["v","Настолько-то мы видим и без бога.",0,367,0,0],["v","Что воинов погублено без счета",0,368,0,0],["v","Ахейцами в погоне за одной",0,368,0,0],["v","Любовишкой, из-за <span class=\"ch\" data-ch=\"elena\">Елены</span> этой!..",0,369,0,0],["v","И то не бред, что мудрый вождь дитя",0,370,0,1],["v","Не пожалел для твари, чтобы брату",0,371,0,0],["v","Вернуть жену… Добро б украли — нет,",0,372,0,0],["v","Сама ушла из Спарты. А ахейцы?<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,373,0,0],["v","Пошли на смерть. Добро б еще предел",0,374,0,0],["v","Отцовский отбивая иль твердыни",0,375,0,0],["v","Родной земли. И если взял Арей",0,376,0,0],["v","Кого из них, тем не пришлось увидеть",0,377,0,0],["v","И сыновей… И пеплосами жен",0,378,0,0],["v","Их мертвые тела не обовьются…",0,379,0,0],["v","В чужой земле лежат. А вдовы где ж?",0,380,0,1],["v","Не дождались и старцы, чтобы кровью",0,381,0,0],["v","Могильный холм их дети оросили.<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,382,0,0],["v","Поистине был славен тот поход!",0,383,0,0],["v","Но затаим постыдное! И Музы<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,384,0,0],["v","Не надо нам, чтоб пела гимны злу…",0,385,0,0],["v","За родину троянцы погибали…",0,386,0,0],["v","Сраженного железом уносили",0,387,0,0],["v","В его чертог, и руки до него",0,388,0,0],["v","Любимые касались, и земля",0,389,0,0],["v","Родимая с его мешалась прахом.",0,390,0,1],["v","А уцелел он — дети и жена",0,390,0,0],["v","Его встречали дома… Разве грех",0,391,0,0],["v","Увидеть их?.. О Гекторе скорбишь ты?",0,392,0,0],["v","Да, он убит, но славен… И лишь греки,",0,393,0,0],["v","Сюда приплыв, прославили его.",0,394,0,0],["v","Сиди они по городам — и кто бы",0,395,0,0],["v","О доблести погибшего слыхал?",0,396,0,0],["v","Парис увез дочь Зевса? На другой",0,397,0,0],["v","Женись Парис — и брак обычный, темный",0,398,0,0],["v","Ему в удел достался б. Если ум",0,399,0,0],["v","В тебе здоров, война тебе претит;",0,400,0,1],["v","Но на войне венец непосрамленный",0,400,0,0],["v","Его детей погибших — вот краса",0,401,0,0],["v","Единая для города; бесславья",0,402,0,0],["v","Нет горшего, чем гибнуть ни за что.",0,403,0,0],["v","Не надо, мать, грустить о Трое больше",0,404,0,0],["v","И обо мне — затем, что наших я",0,405,0,0],["v","Своим венцом злодеев уничтожу.",0,405,0,0],["sp","Корифей"],["v","Как тешат нас над бедствием семьи",0,406,0,0],["v","Неверные, быть может, прорицанья.",0,407,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Когда б не Феб рассудок твой пьянил,",0,408,0,0],["v","Недаром бы вождей Эллады, дева,",0,409,0,0],["v","Такой молвой сопровождала ты",0,410,0,1],["v","Из этих стран, но мудрому придать",0,410,0,0],["v","И важному победа над такою",0,411,0,0],["v","Ничтожностью могла ль бы что, спрошу?",0,412,0,0],["v","Великий царь, Атреев лучший сын,",0,413,0,0],["v","Менадою какой-то очарован.",0,414,0,0],["v","Что я? Бедняк, но даром бы такой",0,415,0,0],["v","Жены не взял. Ты, кажется, рассудком",0,416,0,0],["v","Повреждена, так на твои слова,",0,417,0,0],["v","Для Аргоса обидные, троянка,",0,418,0,0],["v","Мне наплевать. Сама ж — за мною, марш,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,419,0,0],["v","Красавица, к стоянке корабельной!",0,420,0,1],["sd","(<span class=\"ch\" data-ch=\"gekuba\">Гекубе</span>.)"],["v","И ты, жена, когда Лаэртиад",0,421,0,0],["v","Потребует, за ним пойдешь. Хозяйке",0,422,0,0],["v","Достанешься ты скромной, говорят.",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"kassandra\">Кассандра</span>"],["v","Опасный раб! Герольдами зовутся,",0,424,2,0],["v","А всем они одно несчастье, эти",0,425,2,0],["v","Прислужники царей и городов…",0,426,2,0],["v","Ты говоришь, в чертоги Одиссея",0,427,2,0],["sd","(указывает на <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>)"],["v","Она войдет? А Фебовы слова,",0,428,2,0],["v","Через меня сулившие кончину",0,429,2,0],["v","Ей на земле троянской? Но не бранью",0,430,2,1],["v","Мои уста полны теперь. Несчастный",0,430,2,0],["v","Не знает мук грядущих. Что мои,",0,431,2,0],["v","Фригийские что муки? По сравненью —",0,432,2,0],["v","За золото принять их… Десять лет,",0,432,2,0],["v","Что здесь, не в счет — наполнив, возвратится",0,433,2,0],["v","В отчизну он один. А раньше что?",0,434,2,0],["v","И грозная Харибда на скале",0,434,2,0],["v","В теснине, где кружатся волны, и",0,435,2,0],["v","Киклоп, сырым живущий мясом, горный,",0,436,2,0],["v","И Кирка Лигурийская, свиней",0,436,2,0],["v","Формовщица, и горькою пучиной",0,437,2,0],["v","Разбитые ладьи, и лотос, силой",0,438,2,0],["v","Желания влекущий, и коровы,",0,438,2,0],["v","Что Гелию посвящены, и мясо,",0,439,2,0],["v","Которое, заговорив, так горько",0,440,2,1],["v","Покажется Лаэртиаду. Словом,",0,441,2,0],["v","Живой, в Аид сойдет, а избежав",0,442,2,0],["v","Беды морей, он дома встретит беды.<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,443,2,0],["v","Но к чему за чуждой мукой я гоняюсь по пятам?",0,444,0,0],["v","Что же медлю, коль в Аиде брачный пир и нам готов?",0,445,0,0],["v","Вождь данайцев, ты, мечтаний полный гордых о себе,",0,446,0,0],["v","Даже гробу день заказан, ночь открыта твоему.",0,447,0,0],["v","А мое нагое тело в гроб закинут, и потом",0,448,0,0],["v","Занесет его к могиле жениховой. Там меня",0,449,0,0],["v","Звери хищные растащат, Аполлонову слугу.",0,450,0,1],["v","Вы, повязки, дар любовный, Фебов дар, простите ж вы…",0,451,0,0],["v","О, краса моих вещаний… Праздник… Ты уже не мой.",0,452,0,0],["v","О, приблизившись, сорвите мой убор, пока еще",0,453,0,0],["v","Я нетронутая дева. Вещий царь! Я отдаю",0,454,0,0],["v","Всем ветрам твои повязки. Где ж Атридова ладья?",0,455,0,0],["v","Я готова. Долго ль будешь ветра ждать для парусов?",0,456,0,0],["v","О жених мой! Из Эриний, трех Эриний, я одна",0,457,0,0],["v","На твою досталась долю. Ты ж, родимая, не плачь,",0,458,0,0],["v","Троя, родина! Вы, братья под землею! Ты, отец,",0,459,0,0],["v","Что нас поднял! До свиданья: ждите, мертвые, меня:",0,460,0,1],["v","Я сойду к вам, торжествуя и Атридам заплатив.",0,460,0,0],["v","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span> уводит <span class=\"ch\" data-ch=\"kassandra\">Кассандру</span>.",0,461,0,0],["scene","Явление шестое","s8",2,8],["sd","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> одна."],["sp","Корифей"],["v","Кто около <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span>? Что глядите?",0,462,0,0],["v","Без языка царица на земле…",0,463,0,0],["v","Негодницы! Вы бросили лежать",0,464,0,0],["v","Сомлевшую… Да поднимите ж, что ли!",0,465,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не трогайте! И ласка не мила",0,465,0,0],["v","Нам, девушки… Земли холодной лоно —",0,466,0,0],["v","Вот черная награда мук моих",0,467,0,0],["v","Теперешних, и прежних, и грядущих.",0,468,0,0],["v","О боги! в вас союзников зову",0,469,0,0],["v","Я медленных, но все же утешенье",0,470,0,1],["v","Вас призывать в недобрый час. Моих",0,470,0,0],["v","Прошедших благ напоминанье может",0,471,0,0],["v","Растрогать ведь. Царицей я была",0,472,0,0],["v","По роду и по браку, принесла я",0,473,0,0],["v","Блистательных детей — не рядовой",0,474,0,0],["v","Они народ, а цвет фригийцев были.",0,475,0,0],["v","Ни в Трое, ни в Элладе и нигде",0,476,0,0],["v","Таких никто не принесет из женщин,",0,477,0,0],["v","И даром бы хвалиться стали… Их",0,478,0,0],["v","Я видела убитыми, и даром",0,479,0,0],["v","Моих волос курганы их почтили.",0,480,0,1],["v","Приама я оплакала, отца",0,480,0,0],["v","Моих детей, и мне не кто-нибудь",0,481,0,0],["v","Про смерть его поведал, а упал он,",0,482,0,0],["v","Зарезанный, у самого костра",0,483,0,0],["v","Геркейского, и на моих глазах<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,484,0,0],["v","Передо мной горела Троя. Дев",0,485,0,0],["v","Для избранных вскормила женихов я,",0,486,0,0],["v","А их из рук повырвали, и нет",0,487,0,0],["v","Надежды нам увидеться. Но зданья",0,488,0,0],["v","Тяжелых бед вот и карниз: старуха,",0,489,0,0],["v","В Элладе я рабою буду, самых",0,490,0,1],["v","Для старости неподходящих дел",0,491,0,0],["v","Достанется мне бремя, сторожить",0,492,0,0],["v","Мать Гектора заставят их ворота",0,493,0,0],["v","Иль хлеб месить. Спина взамен подушек царских",0,494,0,0],["v","Попробует полов, и земляных.",0,495,0,0],["v","Сквозь жалкие обноски царских риз",0,496,0,0],["v","И кожею истертой… Горе, горе!",0,497,0,0],["v","Из-за одной любви, и сколько мук",0,498,0,0],["v","В глаза еще глядит. <span class=\"ch\" data-ch=\"kassandra\">Кассандра</span>! дочь!",0,499,0,0],["v","Подруга бога, демоном каким<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,500,0,1],["v","Осквернена ты, дева. Поликсена…",0,501,0,0],["v","О, сколько вас, и не придет никто",0,502,0,0],["v","К несчастнейшей… А вы, что поднимали",0,503,0,0],["v","Меня, направьте нежные стопы,",0,504,0,0],["v","Царицыны когда-то, но теперь…",0,505,0,0],["v","Невольничьи, с подстилкою моей",0,506,0,0],["v","Соломенной, к кремнистому обрыву,",0,507,0,0],["v","Чтоб, истомясь слезами, я с него",0,508,0,0],["v","Упала вниз и умерла. А счастья",0,509,0,0],["v","Среди живых не славьте ничьего.",0,510,0,1],["sd","(Опускается на землю.)"],["scene","Первый музыкальный антракт","s9",2,9],["sp","Хор"],["str","Строфа"],["v","Над Илионом, о,",0,511,3,0],["v","О Муза, новою",0,512,3,0],["v","Песнью в слезах обвей",0,513,3,0],["v","Сердце печальное.",0,514,3,0],["v","О Трое мелос мой",0,515,3,0],["v","Будет рыдать…",0,516,3,0],["v","Как от повозки четвероступной, я",0,517,0,0],["v","Горько погибла в горькой неволе,",0,518,0,0],["v","Когда коня нам греки оставили,",0,519,0,0],["v","К небу гремевшего скрытым оружьем,",0,520,0,1],["v","И златоуздого перед воротами.",0,520,0,0],["v","Я помню, как вопил народ,",0,521,2,0],["v","С кремля на чудо глядючи:",0,522,2,0],["v","Конец беде, конец трудам,",0,523,2,0],["v","Вздымайте к Деве идола!",0,524,2,0],["v","То дар для Дия дочери.",0,525,2,0],["v","И кто не шел из девушек,",0,526,0,0],["v","Кто, старый, в дом запрятался?",0,527,0,0],["v","И с песней, торжествуя,",0,528,0,0],["v","Тогда мы завладели",0,529,0,0],["v","Коварною бедой.",0,530,0,1],["str","Антистрофа"],["v","А весь фригийский род",0,531,2,0],["v","К воротам кинулся,",0,532,2,0],["v","Ели в руках зажглись:",0,533,2,0],["v","Хитростью греческой,",0,534,2,0],["v","Хотел купить,",0,535,2,0],["v","Девы бессмертной сердце купить хотим.",0,536,0,0],["v","После канаты чрево обвили,",0,537,0,0],["v","Словно бы остов то корабельный был,",0,538,0,0],["v","И повлекли коня черного к каменным",0,540,0,1],["v","Стенам Палладиным в храм роковой ее.",0,540,0,0],["v","Над тяжкою работою",0,541,2,0],["v","И светлой нашей радостью,",0,542,2,0],["v","Я помню, ночь спустилася,",0,543,2,0],["v","Звучали трубы Ливии,",0,544,2,0],["v","И пляску под родной напев",0,545,2,0],["v","Притопывали девушки,",0,546,2,0],["v","А по домам сморенные",0,547,2,0],["v","Рабыни улеглися,",0,548,2,0],["v","И факелы на спящих",0,549,2,0],["v","Бросали темный блеск.",0,550,2,1],["str","Эпод"],["v","А я, я пляской славила",0,551,0,0],["v","И пела Артемиде",0,552,0,0],["v","В чертоге девы Диевой",0,553,0,0],["v","С подругами. И вдруг резня",0,554,0,0],["v","Объяла город воплями…",0,555,0,0],["v","Дрожащими руками",0,556,0,0],["v","За пеплос материнский",0,557,0,0],["v","Хватались дети, плакали…",0,558,0,0],["v","И покидал Арей",0,560,0,1],["v","Коня Паллады хитрой.",0,560,0,0],["v","Ступени алтарей,",0,561,0,0],["v","Усеянные трупами…",0,562,0,0],["v","И трупы на постелях…",0,563,0,0],["v","И отроки и мы одни;",0,564,0,0],["v","И пустота в домах —",0,565,0,0],["v","Венец Эллады, храбрых",0,565,0,0],["v","Взрастившей сыновей,",0,566,0,0],["v","И траур нашей родины.<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,567,0,0],["act","Действие второе","a3","II"],["sd","ЯВЛЕНИЕ СЕДЬМОЕ Появляется на колеснице <span class=\"ch\" data-ch=\"andromaha\">Андромаха</span> с Астианактом."],["sd","Корифей"],["v","О Гекуба, ты видишь ли там —",0,568,0,0],["v","На повозке нездешней",0,569,1,0],["v","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>: на грудь ей припал",0,570,0,1],["v","Детеныш, Гекторов сын.",0,571,2,0],["v","Куда, на тележном дне,",0,572,1,0],["v","Несчастная едет?",0,573,2,0],["sd","(К <span class=\"ch\" data-ch=\"andromaha\">Андромахе</span>.)"],["v","И медный Гекторов шлем",0,574,1,0],["v","Куда ты везешь, и доспехи фригийцев?",0,575,0,0],["v","Не ими ли сын Ахилла во Фгии",0,576,0,0],["v","Храмы украсит, скажи, нашей добычей?",0,577,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["sd","Строфа I Ахейцы уж рабу увозят!"],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы!",0,578,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Пеан моих стенаний!",1,578,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ай, ай!",0,579,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Пеан моих скорбей!",1,579,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О Зевс!",0,580,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Напев несчастий наших…",1,580,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дети…",0,581,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Что ж… и я жила.",1,581,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","Антистрофа I Ни счастья нет, ни Трои боле."],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Увы!",0,582,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","Расцвет детей прекрасных."],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О горе мне!",0,583,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","И мне, и мне!",1,583,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О, зло!",0,584,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","И мой плачевный жребий.",1,584,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О, город!",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","В прахе и дыму."],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["str","Строфа II"],["v","Возвратись, о муж мой!",0,586,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Тень Аида кроет",0,587,0,0],["v","Сына… Зов напрасен.",0,588,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Защити подругу…",0,590,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","Антистрофа II Ты, о бич ахейцев…"],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Ты, Приам, когда-то",0,591,0,0],["v","Гектора родивший…",0,592,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Нас сведи к Аиду…",0,593,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["str","Эпод"],["v","О, кто жалобы сердца уймет и несносные скорби?",0,594,0,0],["v","Рушилась Троя, и муки над мукой ложатся, что камни,",0,595,0,0],["v","Гневу послушны богов, а сын твой Аида избегнул,",0,596,0,0],["v","Ради жены ненавистной сгубил он троянские башни.",0,597,0,0],["v","Возле храма Паллады кровавые трупы убитых",0,598,0,0],["v","Коршунам можно клевать. И Троя стала рабыней.",0,600,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Горе отчизны моей оплачу, ее покидая.",0,601,0,0],["v","Жалкий ты видишь конец и дом, где детей я рождала.<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,602,0,0],["v","Дети, и город и мать покинуты вами, о дети.",0,603,0,0],["v","О, что за вопли и траур какой…",0,604,2,0],["v","Слезы слезами сменяются.",0,605,2,0],["v","В наших стенах убитому только",0,606,2,0],["v","Муки бесслезной забвенье…",0,607,2,0],["sp","Корифей"],["v","Как сладки вы, о слезы мук священных,",0,608,0,0],["v","И френ, и стон, и горестный напев.",0,609,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О Гектора родившая, что стольких",0,610,0,1],["v","Сгубил врагов, тебе ли видеть нас?<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,610,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Я вижу длань, что вознесла ничтожных,",0,611,0,0],["v","А мнившего, что он велик, разит.",0,612,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Добыча — мы с ребенком. Кровь царей",0,613,0,0],["v","Теперь в рабах. О, ужас перемены!..",0,614,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О меч судьбы! Давно ли от меня",0,615,0,0],["v","Он силою <span class=\"ch\" data-ch=\"kassandra\">Кассандру</span> оторвал?",0,616,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Увы!",0,617,0,0],["v","Другой Аякс для дочери твоей",0,618,0,0],["v","Сыскался, мать. Но все ли горе в этом?",0,619,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Нет им числа, нет меры этих бед.",0,620,0,1],["v","Над головой моей они все спорят.",0,621,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Царевну-дочь зарезали твою",0,622,0,0],["v","На капище Ахилла, Поликсену.",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О, горе мне! Так вот он, тайный смысл",0,624,0,0],["v","Тех давешних <span class=\"ch\" data-ch=\"talfibiy\">Талфибия</span> намеков.",0,625,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","С повозки я спустилась, и покров",0,626,0,0],["v","На мертвую накинула я, плача.",0,627,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы, дитя, безбожным палачам",0,628,0,0],["v","И над твоей, увы, ужасной смертью…",0,629,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Что ж, смерть как смерть, и лучше умереть,",0,630,0,1],["v","Чем жить, как я обречена судьбою.",0,630,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Глядеть, дитя, все ж слаще, чем лежать",0,631,0,0],["v","И быть ничем. Ведь в жизни есть надежда…<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,632,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Послушай, мать. Красивые слова",0,633,0,0],["v","Вдыхают в ум желанную отраду.",0,634,0,0],["v","Я думаю, что не родиться вовсе",0,635,0,0],["v","И умереть — одно и то ж, но смерть",0,636,0,0],["v","Не лучше ли печальной жизни тех,",0,637,0,0],["v","Кто перестал страдать уж по печалям?",0,638,0,0],["v","Но, счастие утратив, ты томишься",0,639,0,0],["v","Прошедших зол воспоминаньем. Дочь",0,640,0,1],["v","Твоя теперь как бы не знала солнца:",0,641,0,0],["v","Она мертва, и зол для ней уж нет.",0,642,0,0],["v","А я вершин достигла счастья, больше",0,643,0,0],["v","И славы бы желать я не могла,",0,644,0,0],["v","И все это уходит.",0,645,0,0],["v","В доме мужа",1,645,0,0],["v","Работам я усердно предавалась,",0,646,0,0],["v","Что скромности приличны женской. Нам",0,647,0,0],["v","Пристал упрек иль не пристал, а если",0,648,0,0],["v","Мы не сидим по теремам, молва",0,649,0,0],["v","Не пощадит. И я сидела в доме,",0,650,0,1],["v","Да и к себе приятных собеседниц",0,650,0,0],["v","Во двор я не пускала. В голове",0,651,0,0],["v","Я свой имею ум, с меня довольно",0,652,0,0],["v","Учителя такого. Не болтала",0,653,0,0],["v","При муже я, и он мое лицо",0,653,0,0],["v","Всегда спокойным видел, а когда",0,654,0,0],["v","Смолчать при нем и на своем поставить",0,655,0,0],["v","Приличнее когда, — я это знала.",0,656,0,0],["v","В ахейский стан слух обо мне прошел,",0,656,0,0],["v","И добрая меня сгубила слава.",0,657,0,0],["v","Как взяли нас, Ахиллов захотел",0,658,0,0],["v","Меня женой иметь наследник в доме.",0,659,0,0],["v","Убийцы Гектора рабыней буду,",0,660,0,1],["v","А памяти ль его мне изменить,",0,661,0,0],["v","Приладившись душою ко второму?",0,662,0,0],["v","Так мертвого обидишь; а того",0,663,0,0],["v","Не полюбить — и он возненавидит…",0,664,0,0],["v","Вот говорят, что с мужем ночь одну",0,665,0,0],["v","Ты проведешь — вражды как не бывало.",0,666,0,0],["v","Но бог с ней, с той вдовой, что позабыть",0,667,0,0],["v","О прошлых ласках может, — кобылица",0,668,0,0],["v","И та, ярмо привычное сыскав,",0,669,0,0],["v","Не так легко мирится. А ведь тварь",0,670,0,1],["v","Не говорит и разумом природой",0,670,0,0],["v","Обделена. Во всем ты, Гектор, взял,",0,671,0,0],["v","Рассудком, и породой, и богатством,",0,672,0,0],["v","И мужеством отличен… Чистой девой",0,673,0,0],["v","Из отчего меня ты дома взял",0,674,0,0],["v","И девичье мне брачным ложе сделал.",0,675,0,0],["v","Ты… ты погиб… а я на корабли",0,676,0,0],["v","С добычею влекусь в Элладу, иго",0,677,0,0],["v","Невольное надевши. Неужели ж",0,678,0,0],["v","Несчастия мои не горше смерти,<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,679,0,0],["v","Которую оплачут. И надежда",0,680,0,1],["v","Кому не лжет, во мне и та молчит,",0,681,0,0],["v","А счастье нас ведь даже в мыслях тешит.",0,682,0,0],["sp","Корифей"],["v","В твоих словах и плаче нахожу",0,683,0,0],["v","Я, женщина, своих несчастий повесть.",0,684,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Мне не пришлось бывать на корабле,",0,685,0,0],["v","Но видела я на картине — люди",0,686,0,0],["v","Рассказывали также, что, пока",0,687,0,0],["v","Все на местах матросы, у руля,",0,690,0,1],["v","Под парусом вычерпывают воду —",0,690,0,0],["v","Как бы спастись, все думают. Но если",0,691,0,0],["v","Взметенная пучина захлестнет,",0,692,0,0],["v","Они, судьбе и бегу волн на волю",0,693,0,0],["v","Себя предав, поборются. Таков",0,693,0,0],["v","Теперь и мой удел: я принимаю",0,694,0,0],["v","Несчастия в молчанье — на меня",0,695,0,0],["v","Обрушилась судьба стеною водной.",0,696,0,0],["v","Дитя мое, старайся позабыть",0,696,0,0],["v","О Гекторе: слезами не воротишь",0,697,0,0],["v","Ты красных дней. Хозяину старайся",0,698,0,0],["v","Понравиться, и нрава своего",0,699,0,0],["v","Ты ласковой пленяй его приманкой —",0,700,0,1],["v","На радость нам. А если внука ты",0,701,0,0],["v","Подымешь, Илиону польза будет",0,702,0,0],["v","Немалая. Ведь правнуки мои",0,703,0,0],["v","Троянское восставить царство могут",0,704,0,0],["v","И город наш.",0,705,0,0],["v","Но погоди, сюда",1,705,0,0],["v","Какого же еще нам шлют герольда",0,706,0,0],["v","Ахейские вожди, что нужно им?",0,707,0,0],["scene","Явление восьмое","s10",3,10],["sd","Входит <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>."],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Храбрейшего когда-то из фригийцев",0,708,0,0],["v","Супруга, нас не осуди. К тебе",0,710,0,1],["v","Не по своей пришел я воле. Речи",0,710,0,0],["v","Данайцев я несу и их вождей.",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О чем же речь? Ее начало страшно.",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","О мальчике вот этом. Как сказать…",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Хозяева, быть может, разлучат нас?",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Нет, в Греции рабом ему не быть.",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Последнего оставят здесь фригийца?",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Не знаю, как смягчить мне мой удар.",0,717,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","Ты очень добр. Но если это счастье…",0,718,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Узнай беду: его должны убить…",0,719,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О злая весть! Ты горше брачной доли.",0,720,0,1],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Всех победил в собранье Одиссей…",0,720,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","О, на одну уж слишком много горя.",0,721,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","…Растить сирот героя запретив.",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["v","На голову б его победа эта!",0,723,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","С твердыни стен троянских сбросят вниз",0,724,0,0],["v","Твое дитя. Так будет. Но разумной",0,725,0,0],["v","Себя яви. Не спорь и будь царицей",0,726,0,0],["v","В своих скорбях. Бессилие сознав,",0,727,0,0],["v","За призраком не увлекайся силы.",0,728,0,0],["v","Откуда ждать опоры — ты подумай…",0,729,0,0],["v","Ни мужа нет, ни царства; ты сама",0,730,0,1],["v","Лишь гостья здесь. У нас же силы хватит",0,731,0,0],["v","Тебя одну сломать. Так не пленяйся ж",0,732,0,0],["v","Борьбой, жена, чтоб злобы не навлечь",0,733,0,0],["v","Ахейской и глумленья — не хотел бы",0,734,0,0],["v","Я слышать и твоих проклятий грекам.",0,735,0,0],["v","Знай — гнев солдат ребенка твоего",0,736,0,0],["v","Поверх земли оставит и бесслезным.",0,737,0,0],["v","А промолчишь — и мертвого дадут",0,738,0,0],["v","Похоронить тебе. Смягчай же греков.",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"andromaha\">Андромаха</span>"],["dir","к сыну"],["v","О милый, дорогой мой, о дитя!",0,740,0,1],["v","Покинешь мать несчастную — врагами",0,740,0,0],["v","Убитый сын, и царственная кровь —",0,741,0,0],["v","Спасенье для других — тебя погубит.",0,742,0,0],["v","Тебе была не в пору знатность, видно, —",0,743,0,0],["v","Несчастное рожденье, горький брак!",0,743,0,0],["v","Иль думала я, в Гекторов чертог",0,744,0,0],["v","Невестою вступая, что придется",0,745,0,0],["v","Мне не царя над Азией рождать,",0,746,0,0],["v","Обильною людьми, а жертву грекам",0,746,0,0],["v","Кровавую? Ты плачешь, сын мой? Разве",0,747,0,0],["v","Ты чувствуешь беду? Как птенчик ты,",0,748,0,0],["v","Что под крыло запрятался, руками",0,749,0,0],["v","За пеплос мой хватаешься. Копье",0,750,0,1],["v","Отцовское бессильно, и земля",0,751,0,0],["v","На Гекторе лежит. И ни родные,",0,752,0,0],["v","Ни твой народ тебе не в помощь. Брошен",0,753,0,0],["v","Вниз головой, безжалостно, дитя,",0,754,0,0],["v","Ты осужден и жизнь отдать. О ноша,",0,755,0,0],["v","Приятней нет для матери! Дыханье",0,756,0,0],["v","Отрадное! Зачем же эта грудь",0,757,0,0],["v","Спеленутым тебя кормила, даром",0,758,0,0],["v","В заботах я крушилась? О, приди",0,759,0,0],["v","И поцелуй меня в последний раз.",0,760,0,1],["v","К родимой припади, обвей руками",0,761,0,0],["v","Мне шею и губами мне к губам",0,762,0,0],["v","Прильни, дитя мое! О греки, вы",0,763,0,0],["v","Такое варварство придумали! Ну чем же",0,764,0,0],["v","Малютка-то виновен? Тиндарида,",0,765,0,0],["v","Не Зевсова ты дочь! Твои отцы —",0,766,0,0],["v","И не один — Аластор и Убийство,",0,767,0,0],["v","И Смерть, и Зависть, и каких Земля",0,768,0,0],["v","Питает только демонов. А Зевс",0,769,0,0],["v","Не мог родить тебя — такое зло",0,770,0,1],["v","Для варваров и эллинов. Проклятье ж",0,770,0,0],["v","Твоим глазам, красивая жена,",0,771,0,0],["v","Сгубившая фригийцев. Нате сына,",0,772,0,0],["v","Утешно вам кидать его, кидайте,",0,773,0,0],["v","Иль, может быть, по вкусу мясо вам",0,774,0,0],["v","Его придется, греки… От богов",0,775,0,0],["v","Погибель наша, и спасти ребенка",0,775,0,0],["v","Я не могу. О, только, бога ради,",0,776,0,0],["v","Хоть в трюм меня поглубже,",0,777,0,0],["v","Несчастную, запрячьте… О, какой",0,778,0,0],["v","Веселый брак для схоронившей сына!",0,779,0,0],["sp","Корифей"],["v","О, сколько ты утратил, Илион,",0,780,0,1],["v","И одного все это жертвы ложа!",0,780,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Мальчик! пора — объятья покинь",0,781,0,0],["v","Матери горькой. На самый верх",0,782,0,0],["v","Башен отцовских тебе",0,783,0,0],["v","Жребий взойти и там",0,784,0,0],["v","Душу оставить… Гей,",0,785,0,0],["v","Подымите его… Герольдом",0,785,0,0],["v","Больше годился бы тут",0,786,0,0],["v","Жалости чуждый, стыдом",0,787,0,0],["v","Менее связанный муж.",0,788,0,0],["v","Астианакта уносят. <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span> и <span class=\"ch\" data-ch=\"andromaha\">Андромаха</span> уходят.",0,789,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дитя, о сын несчастного сына!",0,790,0,1],["v","Неправда твою от нас",0,790,0,0],["v","Жизнь отбирает, от нас,",0,791,0,0],["v","От меня и твоей родимой!",0,792,0,0],["v","Мука какая, и что для тебя",0,792,0,0],["v","Сделать могу я, скажи?",0,793,0,0],["v","Голову стану я бить",0,794,0,0],["v","И грудь не устану терзать,",0,794,0,0],["v","Больше ж во власти моей",0,795,0,0],["v","Нет ничего. Увы мне, увы!",0,796,0,0],["v","За Трою увы! и увы за себя!",0,796,0,0],["v","Какого же горя еще",0,797,0,0],["v","Нам не хватает до полной",0,798,0,0],["v","Гибели, горьким! Увы!",0,798,0,0],["scene","Второй музыкальный антракт","s11",3,11],["sp","Хор"],["str","Строфа I"],["v","Над раздольем для пчел, о царь Теламон,",0,799,0,0],["v","О славный царь Саламина,",0,800,2,1],["v","На прибежище волн у священных брегов,",0,801,0,0],["v","Где серой оливы",0,802,2,0],["v","Показала Паллада впервые красу",0,803,0,0],["v","Светлым Афинам,",0,804,2,0],["v","Снарядился на подвиг ты некогда, царь!",0,805,0,0],["v","И зачем же ты с сыном Алкмены спешил",0,806,0,0],["v","Илион, Илион наш рушить?..",0,807,2,0],["str","Антистрофа I"],["v","Это было в те дни, когда кобылиц",0,808,0,0],["v","Лишен Алкид и разгневан,",0,810,2,1],["v","Цвет Эллады воздвиг и причалил ладьи",0,811,0,0],["v","Близ вод Симоиса.",0,812,2,0],["v","Лаом<em>е</em>донта смерть он горел отомстить…",0,813,0,0],["v","Выпустив стрелы,",0,814,2,0],["v","Стены Феба багровым он пламенем сжег",0,815,0,0],["v","И тебя, Илион. О, горе, о, две,",0,816,0,0],["v","Две осады кровавые Трои!<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,817,2,0],["str","Строфа II"],["v","Видно, и ты, Ганимед,",0,820,0,1],["v","Томный, там у Кронида",0,821,0,0],["v","Между его золотых",0,822,0,0],["v","Полных ступая киафов,",0,823,0,0],["v","Славною службой пленить",0,824,0,0],["v","Тщетно пытался бога?",0,825,0,0],["v","Троя в дыму и огне,",0,826,0,0],["v","Край, родивший тебя…",0,827,0,0],["v","Слышится стон с приморья —",0,828,0,0],["v","Словно птицы птенцов,",0,830,0,1],["v","Жены мужей зовут",0,830,0,0],["v","Или кличут детей",0,831,0,0],["v","Или старую мать.",0,832,0,0],["v","Где же купальни твои,",0,833,0,0],["v","О Ганимед,",0,834,0,0],["v","Игры атлетов? В блеске",0,835,0,0],["v","Зевсова трона твое",0,835,0,0],["v","Лицо молодое спокойно.",0,836,0,0],["v","Нежный еще, ты светел,",0,837,0,0],["v","А Эллада копьем",0,838,0,0],["v","Уж земли Приама сгубила.<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,839,0,0],["str","Антистрофа II"],["v","Слава, Эрот, о Эрот,",0,840,0,1],["v","Божьей волей небесных",0,840,0,0],["v","К Дардану ты низлетел,",0,840,0,0],["v","Трое неся блаженство,",0,840,0,0],["v","Брачный союз в тот век",0,840,0,0],["v","Смертную поросль свил",0,840,0,0],["v","Дивно нашу с богами.",0,840,0,0],["v","Зевса ль мне укорять?",0,840,0,0],["v","Только крылатой Зари",0,840,0,0],["v","Людям страдание зримо:",0,840,0,1],["v","Как унижен Пергам,",0,841,0,0],["v","Зримы пожары Трои.",0,842,0,0],["v","А ведь отсюда Эос",0,843,0,0],["v","Мужа избрала себе,",0,844,0,0],["v","На колеснице к звездам его",0,845,0,0],["v","Дивно умчавши… Где ты,",0,846,0,0],["v","Наша надежда?",0,847,0,0],["v","Ты Трое великой казалась…",0,848,0,0],["v","Только любовь у смертных",0,849,0,0],["v","Больше не с нами… О!",0,850,0,0],["v","Для Трои она бесполезна.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,851,0,0],["act","Действие третье","a4","III"],["scene","Явление девятое","s12",4,12],["sd","Входит <span class=\"ch\" data-ch=\"menelay\">Менелай</span>."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, солнца блеск сияющий, о, день,",0,860,0,1],["v","Который мне отдаст жену! Напрасно",0,861,0,0],["v","Здесь думают, однако, что меня",0,862,0,0],["v","Сюда влекла <span class=\"ch\" data-ch=\"elena\">Елена</span>. Отомстить",0,863,0,0],["v","Укравшему ее из Спарты гостю",0,864,0,0],["v","Явился я. И с помощью богов",0,865,0,0],["v","Возмездье он уже понес. Не встанут",0,866,0,0],["v","Ни он, ни край его: поражены",0,867,0,0],["v","Копьем они ахейским. Я ж отсюда",0,868,0,0],["v","Себе возьму спартанку. Неприятно",0,869,0,0],["v","Женой ее назвать, хотя моей",0,870,0,1],["v","Женой она была, и точно — в общем счете",0,870,0,0],["v","Среди рабынь троянских этот дом",0,871,0,0],["v","Ее таил. Добытчики ее",0,872,0,0],["v","Мне отдали казнить, а пожелаю —",0,873,0,0],["v","Так и живьем с собою в Аргос взять.",0,874,0,0],["v","И я решил, что в Трое жизнь <span class=\"ch\" data-ch=\"elena\">Елене</span>",0,875,0,0],["v","Оставлена должна быть. На корабль",0,876,0,0],["v","Я посажу ее, и пусть в Элладе",0,877,0,0],["v","Насытятся ее убийством все,",0,878,0,0],["v","Которые здесь потеряли близких.",0,879,0,0],["sd","(К слугам.)"],["v","Гей, вы, в шатер ступайте да оттуда",0,880,0,1],["v","К нам за косу тащите эту тварь,",0,880,0,0],["v","Запятнанную кровью. Только б ветра",0,881,0,0],["v","Попутного дождаться — и в Элладу…",0,882,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","молитвенно"],["v","О ты, земле движенье и престол",0,883,0,0],["v","Избравший на земле, кто б ни был ты,",0,884,0,0],["v","Непостижимый Зевс, природы ль сила",0,885,0,0],["v","Иль разум наш, но я тебя молю:<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,886,0,0],["v","Пути твои сокрыты, но ведешь ты",0,887,0,0],["v","Все смертное, о боже, справедливо.",0,888,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты молишься по-новому, жена.",0,889,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Желание твое убить жену",0,890,0,1],["v","Я, Менелай, хвалю. Беги, однако,",0,890,0,0],["v","От прелести ее, чтобы желанью",0,891,0,0],["v","Не уступить. Она глаза мужчин",0,891,0,0],["v","Берет легко, твердыни, даже те",0,892,0,0],["v","Не устоят пред нею, и дома",0,893,0,0],["v","Она палит… О, сколько чары в этой",0,893,0,0],["v","Прелестнице! Мы, впрочем, знаем сколько:",0,894,0,0],["v","И ты, и я, и все, кто испытал…",0,895,0,0],["scene","Явление десятое","s13",4,13],["v","Слуги вытаскивают из шатра <span class=\"ch\" data-ch=\"elena\">Елену</span>.",0,895,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О Менелай… Начало это ужас",0,896,0,0],["v","Поистине сулит в руках твоих",0,896,0,0],["v","Приспешников. И силой из шатра",0,897,0,0],["v","Приведена к тебе я. Ненавистна",0,898,0,0],["v","Тебе я, царь, я знаю, но услышать",0,898,0,0],["v","Свой приговор хотела б я. Народ",0,899,0,0],["v","И ты с моей как жизнью порешили?",0,900,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ну, об тебе не спорили. Тебя",0,900,0,0],["v","Весь лагерь мне отдать решил ахейский.",0,901,0,0],["v","Я пострадал, я буду и казнить.",0,902,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но доказать не смею ли, что смерти",0,903,0,0],["v","Хотите вы моей несправедливо?",0,904,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не разговор у нас, а приговор.",0,905,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Царь, выслушай ее. Пристойней кара,",0,906,0,0],["v","Когда была защита. Но сказать",0,907,0,0],["v","Позволь и нам в улику ей. Ты здешних",0,908,0,0],["v","Не знаешь зол. Все вместе и решит",0,909,0,0],["v","Ее судьбу… А сети будут крепки.",0,910,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нам недосуг. Но так и быть, пускай",0,910,0,0],["v","Поговорит. Тебя хочу послушать:",0,911,0,0],["v","Из-за нее не стоило б и ждать.",0,912,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты доводов моих, пожалуй, царь,",0,913,0,0],["v","И разбирать не станешь, без ответа",0,914,0,0],["v","Оставишь их, как доводы врага, —",0,915,0,0],["v","А все ж за мной черед. Так получай же",0,916,0,0],["v","В ответ своим, несказанным, мои,",0,917,0,0],["v","О Менелай, иль наши обвиненья…",0,918,0,0],["sd","(Указывая на <span class=\"ch\" data-ch=\"gekuba\">Гекубу</span>.)"],["v","Вот спрашивай с кого! Здесь — корень зол:",0,919,0,0],["v","Родившая Париса. После ж этой",0,920,0,1],["v","Нас погубил — и Трою и меня —",0,920,0,0],["v","Старик Приам: зачем Париса он,",0,921,0,0],["v","То факела подобье роковое,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,922,0,0],["v","Оставил жить? Ты проследи-ка, царь,",0,923,0,0],["v","Отсюда то, что вышло… Александру,",0,924,0,0],["v","Когда судьей меж трех богинь он стал,",0,925,0,0],["v","Обещано Палладой торжество",0,925,0,0],["v","Над Грецией с фригийской ратью было,",0,926,0,0],["v","А Гера царство Азии ему",0,927,0,0],["v","И материк Европы посулила,",0,928,0,0],["v","И наконец, Киприда красотой",0,929,0,0],["v","Моей его манила. В эти речи",0,930,0,1],["v","Ты вдумайся. Киприда побеждает",0,930,0,0],["v","Тех двух богинь. Кому же, как не вам,",0,931,0,0],["v","Я помогла? Ни варварские копья,",0,932,0,0],["v","Ни их ярмо сломить вы не могли…",0,933,0,0],["v","Ты процвела, Эллада… Я ж погибла…",0,934,0,0],["v","Моя краса — под игом, и кому",0,935,0,0],["v","Ее венчать бы надо, те позорят.",0,936,0,0],["v","Но отчего, ты скажешь, не коснусь я",0,937,0,0],["v","Ближайшего — увоза… Слушай: этот",0,938,0,0],["v","Аластор, он ведь прибыл не один,",0,939,0,0],["v","Богиня с ним была, и страшной силы…",0,940,0,1],["v","Как демона назвать того: Парис",0,940,0,0],["v","Иль Александр? Но ты зачем же, жалкий,",0,941,0,0],["v","Его оставил в доме и зачем",0,942,0,0],["v","Нелегкая тебя на Крит носила?",0,943,0,0],["v","А впрочем, пусть…",0,944,0,0],["v","Теперь себя я самое спрошу:",0,945,0,0],["v","Что в мыслях я держала, с этим гостем",0,946,0,0],["v","Пускаясь в путь, отчизну и очаг",0,947,0,0],["v","Предавшая? Но взыскивай с богини,",0,948,0,0],["v","Коль Зевса ты сильнее: Зевс царит",0,949,0,0],["v","Среди богов, а этой только служит.",0,950,0,1],["v","Простите же меня. Но раньше ваш",0,950,0,0],["v","Оспорю я и точно сильный довод.",0,951,0,0],["v","Когда Парис сошел в подземный мир",0,952,0,0],["v","И созданный богами брак был кончен,",0,953,0,0],["v","Тогда зачем, покинув царский дом,",0,953,0,0],["v","На корабли аргосцев не пришла я?",0,954,0,0],["v","О, сколько раз пыталась, — вы о том",0,955,0,0],["v","Свидетелей-привратников спросите",0,956,0,0],["v","Да караул на башнях. Сколько раз,",0,956,0,0],["v","Уж до земли до самой на веревке",0,957,0,0],["v","Спускался, я достигала… Нет,",0,958,0,0],["v","Таки изловят. Силою, фригийцам",0,959,0,0],["v","Наперекор, тут Деифоб однажды",0,960,0,1],["v","Мной овладел. О Менелай, о муж!",0,960,0,0],["v","Твоя ль рука казнит меня за то, что",0,961,0,0],["v","Я уступила силе, и за мой",0,962,0,0],["v","Единственный венец, за горечь рабства?",0,963,0,0],["v","Иль точно ты задумал быть сильней",0,964,0,0],["v","Самих богов? Какое ослепленье!..",0,965,0,0],["sp","Корифей"],["v","О, заступись, царица, за детей",0,966,0,0],["v","И родину — разрушь ты эти чары,",0,967,0,0],["v","Как говорит злодейка — страх берет.",0,968,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Я заступлюсь сначала за бессмертных.",0,969,0,0],["v","В ее словах — неправда. Никогда",0,970,0,1],["v","Не допущу и мысли, чтобы Гера,",0,971,0,0],["v","Или Паллада-Дева снизошли",0,972,0,0],["v","До глупых обещаний, та — Афин,",0,973,0,0],["v","Та — Аргоса фригийцу. Не тщеславье",0,974,0,0],["v","Влекло богинь на Иду, а игра.",0,975,0,0],["v","Откуда б и огонь такой у Геры",0,976,0,0],["v","Слыть первою красавицей?.. Иль ей",0,977,0,0],["v","Мечтался муж сильнее Зевса? Та ли,",0,978,0,0],["v","Которой Зевс, склоняясь на мольбы,",0,979,0,0],["v","Дал чистоту навеки, возжелала",0,980,0,1],["v","Божественного брака? Нет. Зачем",0,980,0,0],["v","Прикрасою своих несчастий слабость",0,981,0,0],["v","Богов творить? Ведь умных все равно",0,982,0,0],["v","Не убедишь ты этим. Иль Киприду?",0,983,0,0],["v","Заставила — как на смех — приезжать",0,983,0,0],["v","В спартанский дом зачем-то с Александром.",0,984,0,0],["v","Как будто бы она тебя, с небес",0,985,0,0],["v","Не трогаясь, была метнуть не в силах<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,986,0,0],["v","С Амиклами твоими в Илион?",0,986,0,0],["v","На диво был красив мой сын, вот ум",0,987,0,0],["v","Твой, женщина, и сделался Кипридой,",0,988,0,0],["v","Его узрев. Слепая страсть у нас",0,989,0,0],["v","Так и слывет безумной Афродитой.",0,990,0,1],["v","Он золотом убора и красой",0,990,0,0],["v","Своей одежды варварской в тебе",0,991,0,0],["v","Любовь зажег. Ты в Аргосе жила ведь<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,992,0,0],["v","Без роскоши и, Спарту покидая,",0,993,0,0],["v","Надеялась, пожалуй, что течет",0,993,0,0],["v","Здесь золото рекою и его",0,994,0,0],["v","Расходовать дадут тебе, как воду:",0,995,0,0],["v","Спартанский дом мечты твоей не мог",0,996,0,0],["v","Изнеженной насытить… Ну, а дальше?",0,996,0,0],["v","Ты говоришь, что силою мой сын",0,997,0,0],["v","Тебя увлек. Кто ж это видел в Спарте?",0,998,0,0],["v","К кому же ты взывала, что к тебе",0,999,0,0],["v","Ни Кастор, ни близнец его на помощь",0,1000,0,1],["v","Не кинулись, тогда еще не звезды?..<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1000,0,0],["v","Но вот и в Трое ты, а за тобой",0,1001,0,0],["v","Аргосцы по пятам… Война… И что же?",0,1002,0,0],["v","Чуть слух побед, бывало, об успехе",0,1003,0,0],["v","Спартанского царя, его хвала",0,1003,0,0],["v","Слетает с губ твоих, — ты и не помнишь,",0,1004,0,0],["v","Что огорчен в Парисе не один",0,1005,0,0],["v","Ахейский враг, но и соперник царский.",0,1006,0,0],["v","А Троя верх возьмет — в твоих глазах",0,1006,0,0],["v","Вновь <span class=\"ch\" data-ch=\"menelay\">Менелай</span> ничтожен. Вообще",0,1007,0,0],["v","Искала ты лишь дружбы, счастья. Доблесть",0,1008,0,0],["v","Тебе была неинтересна. Вот",0,1009,0,0],["v","Ты говоришь, что будто на веревке",0,1010,0,1],["v","Со стен тайком спускалась, что тебя",0,1010,0,0],["v","Насильно мы держали. Может быть,",0,1011,0,0],["v","Готовила ты петлю или меч,",0,1012,0,0],["v","Как свойственно жене благорожденной",0,1013,0,0],["v","В тоске по прежнем муже? Сколько раз,",0,1014,0,0],["v","Припомни-ка, тебе внушала я:",0,1015,0,0],["v","Спасайся, дочь! А мы своих поженим.",0,1015,0,0],["v","До кораблей ахейских помогу",0,1016,0,0],["v","Сама тебе добраться, только бойню",0,1017,0,0],["v","Меж греками и Троей прекрати.",0,1018,0,0],["v","Да, видимо, нам не по вкусу было.",0,1019,0,0],["v","Надменная, в чертоге Александра",0,1020,0,1],["v","Хотела ты, чтоб варвары тебя",0,1020,0,0],["v","Земным поклоном чтили. Вот о чем",0,1021,0,0],["v","Была твоя забота. Разрядилась",0,1022,0,0],["v","И глаз своих лучи мешать дерзает",0,1023,0,0],["v","С властителем своим законным… Тварь…",0,1024,0,0],["sd","(К хору.)"],["v","Ей надо бы униженно, в лохмотьях,",0,1025,0,0],["v","Ей с трепетом, с обритой головой",0,1025,0,0],["v","Сюда идти бы надо, за грехи",0,1026,0,0],["v","Прошедшие смирением платить",0,1027,0,0],["v","Да с лихвою бесстыдство выкупая.",0,1028,0,0],["v","О Менелай, последние тебе",0,1029,0,0],["v","Мои слова: царь, увенчай Элладу,",0,1030,0,1],["v","Казни свою жену, и пусть закон",0,1030,0,0],["v","Отныне жен неверных убивает.",0,1031,0,0],["sp","Корифей"],["v","О Менелай! Достойно дома предков",0,1032,0,0],["v","Сними с себя укор Эллады всей,",0,1033,0,0],["v","Что духом слаб. Будь царь перед врагами.",0,1034,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Мы сходимся с тобою в мыслях. Дом",0,1035,0,0],["v","Покинула для брака с чужестранцем",0,1035,0,0],["v","Она сама. Киприда — для уловки",0,1036,0,0],["v","В ее словах.",0,1037,0,0],["sd","(К <span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","Ступай: близ палачей,",0,1038,4,0],["v","Готовящих каменья, скорой смертью",0,1039,0,0],["v","Искупить ты года ахейских мук",0,1040,0,1],["v","И, выгодно ль позорить нас, поймешь…",0,1040,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ниц пав, молю у ног твоих… в недуге",0,1041,0,0],["v","Вина богов, а не моя… Прости!",0,1042,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не предавай убитых ею, царь,",0,1043,0,0],["v","Союзников твоих: тебя их тени",0,1044,0,0],["v","И сыновья мои с <span class=\"ch\" data-ch=\"gekuba\">Гекубой</span> молят.",0,1045,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ну, перестань, старуха. С нею мы",0,1046,0,0],["v","Покончили покуда. В корабельный",0,1047,0,0],["v","Я трюм ее спустить велел рабам.",0,1048,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Но не на том, где сам поедешь, судне.",0,1049,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль думаешь, что груз уж так велик?",0,1050,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Не груз велик. Неизлечим любовник.",0,1050,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Коль он любим. А если нет?.. Тогда?..",0,1051,0,0],["v","Но все же пусть по-твоему. Мы розно",0,1052,0,0],["v","Поедем с ней. В твоих словах есть правда.",0,1053,0,0],["v","А в Аргосе злодейку поделом",0,1054,0,0],["v","Постигнет злая кара. Всем урок",0,1055,0,0],["v","Вам, женщины, хоть не скажу, чтоб легкий.",0,1056,0,0],["v","Он ужасом проймет и слепоту,",0,1057,0,0],["v","Найдись меж жен моей еще бесстыдней.",0,1058,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елену</span> уводят, <span class=\"ch\" data-ch=\"menelay\">Менелай</span> уходит.",0,1059,0,0],["scene","Третий музыкальный антракт","s14",4,14],["sp","Хор"],["str","Строфа I"],["v","Храм ли свой Илиона, храм,",0,1060,0,1],["v","Алтарей ли куренья",0,1061,0,0],["v","Предал эллинам, боже, ты?",0,1062,0,0],["v","Пламя ль жертвы бескровное,",0,1063,0,0],["v","На твердыне ль святой",0,1064,0,0],["v","Мирры нежный дух?..",0,1065,0,0],["v","Иды дол кипарисный весь,",0,1066,0,0],["v","Снега талого весь залит фиалкою,",0,1067,0,0],["v","Высь далекая под лобзаньями",0,1068,0,0],["v","Солнца первая Бог забыл вас, бог!",0,1070,0,1],["str","Антистрофа I"],["v","Ваши жертвы развеяны,",0,1070,0,0],["v","Ваши хоры богам, увы,",0,1071,0,0],["v","Во всю ночь не звучать им,",0,1072,0,0],["v","О злаченые идолы,",0,1073,0,0],["v","Где краса ваша, где,",0,1074,0,0],["v","Радость Фригии,",0,1075,0,0],["v","Где двенадцать лун?<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1076,0,0],["v","Душно, душно мне. С трона гордого",0,1077,0,0],["v","Там, в эфире, царь, рассмотрел ли ты,",0,1078,0,0],["v","Что погибли мы в твоем городе,",0,1079,0,0],["v","Что поток унес его пламенный?",0,1080,0,1],["str","Строфа II"],["v","О милый, о муж мой, тенью",0,1081,0,0],["v","Не погребен, не омытый,",0,1082,0,0],["v","Тенью пока ты бродишь,",0,1083,0,0],["v","Меня унести по волнам",0,1084,0,0],["v","Ладья распустила крылья",0,1085,0,0],["v","В тот Аргос, конями славный,",0,1086,0,0],["v","Где стен Киклопов",0,1087,0,0],["v","Твердыня уходит в небо.",0,1088,0,0],["v","Тут дети толпой в воротах",0,1089,0,0],["v","Сошлись. Там слезы и вопли:",0,1090,0,1],["v","\"О мать! Одного ахейцы",0,1091,0,0],["v","Вдаль от тебя уводят —",0,1092,0,0],["v","Но если корабль смоленый",0,1093,0,0],["v","И весла, в море купаясь,",0,1094,0,0],["v","Умчать уж меня грозятся, —",0,1095,0,0],["v","На тот Саламин ли священный",0,1096,0,0],["v","Или на Истм, где выси",0,1097,0,0],["v","Путину морскую рассекли",0,1098,0,0],["v","На страже у врат Пелопа…\"",0,1099,0,0],["str","Антистрофа II"],["v","О, дай бог ладье спартанца,<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1100,0,1],["v","Когда на открытом море",0,1100,0,0],["v","Качать ее будут волны,",0,1101,0,0],["v","Дай бог, чтобы пламя перуна",0,1102,0,0],["v","Ладью спартанцев рассекло.",0,1103,0,0],["v","Зачем он меня из Трои",0,1103,0,0],["v","В слезах, рабыню, уносит",0,1104,0,0],["v","В Элладу? А та, дочь Зевса,",0,1105,0,0],["v","За то, что у нас золотую",0,1106,0,0],["v","Отраду зеркал девичьих<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1106,0,0],["v","Взяла, — да не даст ей вышний",0,1107,0,0],["v","Увидеть родную землю,",0,1108,0,0],["v","Отцовский очаг и дом.",0,1109,0,0],["v","И царь спартанский пускай бы",0,1110,0,1],["v","Своей не видал Питаны,",0,1111,0,0],["v","Ни медных ворот богини.<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,1112,0,0],["v","Брак его был позорный,",0,1113,0,0],["v","На горе великой Элладе,",0,1114,0,0],["v","На муку брегам Скамандра.",0,1115,0,0],["act","Исход","a5",""],["scene","Явление одиннадцатое","s15",5,15],["sd","Входит <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>, за ним вносят мертвое тело Астианакта."],["sp","Корифей"],["v","Увы, увы!",0,1116,2,0],["v","Беда за бедой, сменяясь, идут",0,1117,0,0],["v","По нашей земле.",0,1118,2,0],["v","Глядите, печальные жены:",0,1119,0,0],["v","Вот Гекторов сын, убили его,",0,1120,0,1],["v","С высокой стены данайцы его",0,1120,0,0],["v","Жестокие сбросили вниз.",0,1121,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Гекуба, я к тебе. У берегов",0,1122,0,0],["v","Из кораблей Неоптолема плещет",0,1123,0,0],["v","Последний — он везти остатки должен",0,1124,0,0],["v","Его добыч во Фтию. Сам же царь,",0,1125,0,0],["v","Услышав о несчастии Пелея,",0,1126,0,0],["v","Которого прогнал Акает, на помощь<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",0,1127,0,0],["v","К нему поплыл немедля. И хотелось",0,1128,0,0],["sd","Троянки"],["v","Ему еще остаться, да нельзя.",0,1129,0,0],["v","И Гектора вдову он взял. О, сколько",0,1130,0,1],["v","Я пролил слез из-за нее, когда",0,1130,0,0],["v","С отчизною она прощалась, плача,",0,1131,0,0],["v","И с Гектора могилой. Господин",0,1132,0,0],["v","Позволил ей похоронить ребенка.",0,1133,0,0],["v","Вот он, твой внук, — низвеянный со стен",0,1134,0,0],["v","И горестно отдавший душу. Было",0,1135,0,0],["v","Обещано им также медный щит,",0,1135,0,0],["v","Которым нас пугал, бывало, Гектор,",0,1136,0,0],["v","Товарища его, не отправлять",0,1137,0,0],["v","К Пелеевым святыням в тот чертог,",0,1138,0,0],["v","Где муж ее обнимет новый. Там",0,1139,0,0],["v","Ей этот блеск тяжел бы был. Так пусть же",0,1140,0,1],["v","Ребенку он заменит гроб кедровый",0,1140,0,0],["v","И камень гробовой. Передаю",0,1141,0,0],["v","Тебе его останки. В пеплос внука",0,1142,0,0],["v","Завей, венками тихо убери,",0,1143,0,0],["v","Ну, сколько можешь, чем еще найдется…",0,1144,0,0],["v","Уж потрудись за мать, за <span class=\"ch\" data-ch=\"andromaha\">Андромаху</span>.",0,1145,0,0],["v","Остаться муж ей не дал. А когда",0,1146,0,0],["v","Ты уберешь покойника, землей",0,1147,0,0],["v","Засыплем гроб мы сами и в могилу",0,1148,0,0],["v","Копье вонзим. Но не теряй минут…",0,1149,0,0],["v","Часть дела я уж за тебя исполнил:",0,1150,0,1],["v","В Скамандре труп я выкупал, я раны",0,1151,0,0],["v","Его омыл дорогой. И могилу",0,1152,0,0],["v","Вот выроем, потрудимся. Зараз",0,1153,0,0],["v","Покончить бы — да и домой пора бы.",0,1154,0,0],["sd","(Уходит.)"],["sd","Рабы после первых слов <span class=\"ch\" data-ch=\"gekuba\">Гекубы</span>, сложивши щит, следуют за ним."],["scene","Явление двенадцатое","s16",5,16],["sd","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> и хор."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Сюда его кладите щит! Увы!",0,1155,0,0],["v","О, горький вид и тягостный! Ахейцы,",0,1156,0,0],["v","В вас больше сил, чем доблести, должно быть.",0,1157,0,0],["v","Кто испугал, убийцы, вас? Ребенок…",0,1160,0,1],["v","Боялись вы, чтоб он когда-нибудь",0,1160,0,0],["v","Восстановить не вздумал Трою? Сами ж",0,1161,0,0],["v","После того вы были что? Сгубив",0,1162,0,0],["v","Нас, несмотря на Гектора и столько",0,1163,0,0],["v","Фригийских сил, и стены наши взяв,",0,1163,0,0],["v","Малютки вы боитесь? Горе страху,",0,1164,0,0],["v","Когда темнит рассудок…",0,1165,0,0],["v","Голубь мой!",1,1165,0,0],["v","Какая смерть бесславная… Отчизне,",0,1166,0,0],["v","И той ты не достался. Не вкусил",0,1166,0,0],["v","Ни юности, ни брака и с богами",0,1167,0,0],["v","На царстве не был ранен. Ты бы мог",0,1168,0,0],["v","Познать блаженство это — если точно",0,1169,0,0],["v","Так счастлив царь… Все как во сне увидеть",0,1170,0,1],["v","И умереть, не овладев ничем…",0,1170,0,0],["v","Дитя, какая участь! Вот следы",0,1171,0,0],["v","Отцовских стен… вся голова разбита",0,1172,0,0],["v","О Фебову твердыню. Ты, о сад,",0,1173,0,0],["v","Где матери уста блуждать любили!",0,1174,0,0],["v","А из костей раздробленных… глядит,",0,1175,0,0],["v","Зияя, кровь… Как опозорен, боже…",0,1176,0,0],["v","О руки — рук отцовских дивных слепок,",0,1177,0,0],["v","Тех милых рук; суставы ваши смяты…",0,1178,0,0],["v","О губы, ты, о прелесть детской клятвы,",0,1179,0,0],["v","Вас больше нет. Зачем ты обманул",0,1180,0,1],["v","Меня тогда, держа за пеплос, помнишь,",0,1180,0,0],["v","Что на мою могилу, не жалея,",0,1181,0,0],["v","Ты локонов насыплешь и друзей",0,1182,0,0],["v","Ты приведешь почтить меня приветом?",0,1183,0,0],["v","Не ты меня, я, старая, тебя,",0,1184,0,0],["v","Изгнанница бездомная, засыплю.",0,1185,0,0],["v","О, сколько вас погибло, поцелуев,",0,1186,0,0],["v","Забот и снов, что сладко прерывались.",0,1187,0,0],["v","И что ж поэт надгробием бы взял",0,1188,0,0],["v","Твоим, дитя? \"Здесь некогда аргосцы",0,1189,0,0],["v","Убили мальчика из страха\". Эпиграмм",0,1190,0,1],["v","Позорнее Элладе не писали…",0,1190,0,0],["v","Все ж обделить не удалось, хороним",0,1191,0,0],["v","Дитя в щите отцовском…",0,1192,0,0],["v","Здравствуй, щит!..",1,1192,0,0],["v","Ты охранял красу руки геройской,",0,1193,0,0],["v","Но самого защитника не спас.",0,1194,0,0],["v","Вот на кольце отрадный след от пальцев.",0,1195,0,0],["v","Тут пот царя овалами бежал",0,1195,0,0],["v","С его лица, когда порой, измучен,",0,1196,0,0],["v","Он подносил к пылающей щеке",0,1197,0,0],["v","Тебя, о щит!",0,1198,0,0],["sd","(К женщинам.)"],["v","Но этот труп несчастный",0,1199,4,0],["v","Покройте ж чем найдется, все несите,",0,1200,0,1],["v","Что только есть у нас. Мне не дано",0,1200,0,0],["v","Убрать тебя красиво, но получишь",0,1201,0,0],["v","Последнее зато ты. Слепы вы,",0,1202,0,0],["v","О смертные, коль радует вас прочность",0,1203,0,0],["v","Случайных благ. Судьба — как человек,",0,1204,0,0],["v","Что разума лишился… Сумасбродны",0,1205,0,0],["v","Ее прыжки… Кто счастье покорит?..",0,1206,0,0],["sd","(<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span> плача припадает к телу. Долгая пауза.)"],["sp","Корифей"],["dir","указывая <span class=\"ch\" data-ch=\"gekuba\">Гекубе</span> на женщин, которые несут из шатра уборы для погребения"],["v","Вот: женщины собрали, что осталось",0,1207,0,0],["v","От грабежа… Одень же мертвеца.",0,1208,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["dir","принимая убор, одевает Астианакта"],["v","Не праздновать меж сверстников победу",0,1209,0,0],["v","На четверне, на стрельбище ль, дитя",0,1210,0,1],["v","(Обычаи, любезные фригийцам",0,1210,0,0],["v","Не менее, чем грекам) — я тебе",0,1211,0,0],["v","Дарю убор: ты матери отцовским",0,1212,0,0],["v","Украсить дай себя своим добром,<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,1213,0,0],["v","Остатком от твоих сокровищ. Их",0,1214,0,0],["v","Разграбила <span class=\"ch\" data-ch=\"elena\">Елена</span>, эта язва,",0,1215,0,0],["v","Сгубившая тебя и царский дом…",0,1215,0,0],["sp","Хор"],["v","Ой! Сердца, сердца коснулась ты…",0,1216,0,0],["v","Царь мой, царь бы он был для нас…",0,1217,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","На брачный пир и с первой из невест",0,1218,0,0],["v","Всей Азии готовила тебе я",0,1219,0,0],["v","Такой наряд. И им одену труп.",0,1220,0,1],["v","А ты, доспех отцовский, что трофеев",0,1220,0,0],["v","Без счета нам стяжал, венчай его",0,1221,0,0],["v","И с мертвецом, сам смерти не вкусивший,",0,1222,0,0],["v","Сойди во мрак. Как жалок пред тобой",0,1223,0,0],["v","Щит хитреца и труса — Одиссея.<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,1224,0,0],["v","Начинается обряд похорон.",0,1225,0,0],["sp","Хор"],["v","Увы! Увы!",0,1226,0,0],["v","Со стоном, с горькой жалобой",0,1227,0,0],["v","Прими его, земля!",0,1228,0,0],["v","Стенай, о мать!..",0,1229,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ой, лишенько!",1,1229,0,0],["sp","Хор"],["v","Рыданием надгробным.",0,1230,0,1],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О!..",0,1230,0,0],["sp","Хор"],["v","Вы, муки несказанные!",0,1231,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Повязками его лечу я раны;",0,1232,0,0],["v","Но жалко: я, лишь по названью врач,",0,1233,0,0],["v","Не исцелю… Отец тебе поможет…",0,1234,0,0],["sp","Хор"],["v","Не щади ее, не щади больной!",0,1235,0,0],["v","Как веслом ее, голову, голову —",0,1235,0,0],["v","О-ой, боже мой, боже мой!",0,1236,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О женщины, подруги!",0,1237,0,0],["sp","Хор"],["v","Что? что же, Гекуба?",0,1238,0,0],["v","Бедная, что тебе?..",0,1239,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Лишь муки мне богами суждены,",0,1240,0,1],["v","И Илион их ненавистью избран.",0,1241,0,0],["v","Вот наших жертв успех… Но если б бог",0,1242,0,0],["v","Не приравнял гордыни нашей праху,",0,1243,0,0],["v","В безвестности б остались мы… И плач",0,1244,0,0],["v","Не разгласил бы в мире нашей славы.",0,1245,0,0],["v","Сложите в гроб останки эти. Их<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,1246,0,0],["v","Почтим как следует. А пышность",0,1247,0,0],["v","Для мертвого ничтожна. Лишь живым",0,1248,0,0],["v","Кичливую несет она отраду.",0,1250,0,1],["sd","Труп уносят."],["sp","Корифей"],["v","Увы! Увы!",0,1250,0,0],["v","Ты, бедная, сколько надежд у тебя",0,1251,0,0],["v","На сына цветущего было…",0,1252,0,0],["v","Разбились они,",0,1253,0,0],["v","Как ты, о дитя, что с высей блестящих",0,1254,0,0],["v","Смерти низринут в голодную пасть…",0,1255,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Га! Что ж это? что?",0,1255,0,0],["v","Там, наверху?",0,1256,0,0],["v","Какие-то люди и факелы ходят,",0,1257,0,0],["v","Сверкая? На Трою еще ли",0,1258,0,0],["v","Недуг ополчился?<a class=\"nr\" href=\"#n-k48\" data-n=\"k48\" aria-label=\"Примечание 48\">48</a>",0,1259,0,0],["scene","Явление тринадцатое","s17",5,17],["sd","Те же и <span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span> с солдатами, несущими факелы."],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Назначенным для поджиганья Трои",0,1260,0,1],["v","Вот мой приказ. Пусть больше не хранят",0,1261,0,0],["v","Своих огней сиянье праздным. Дайте",0,1262,0,0],["v","Ему лизнуть добычу, о лохаги,",0,1263,0,0],["v","Чтоб, Илион сровняв с землей, спокойно",0,1264,0,0],["v","Отбыть домой могли мы. Вы же, дщери",0,1265,0,0],["v","Троянские, — по знаку моему,",0,1266,0,0],["v","Едва трубу услышите вождей,",0,1267,0,0],["v","Все в гавань марш, и в путь. А ты, старуха,",0,1268,0,0],["v","Ты, самая несчастная из жен,",0,1269,0,0],["v","Отправишься вот с ними: Одиссей",0,1270,0,1],["v","По жребию везет тебя рабою…",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О горе мне! Уж дальше и мое,",0,1272,0,0],["v","Куда идти, несчастие не знает.",0,1273,0,0],["v","В изгнание — и из горящей Трои.",0,1274,0,0],["v","Вы, старые, все ж поспешите, ноги,",0,1275,0,0],["v","Хоть попрощаться с Троей. От нее,",0,1276,0,0],["v","Великой и меж варваров надменной,",0,1277,0,0],["v","Не славное ль сейчас возьмут и имя?..",0,1278,0,0],["v","Ее огонь, а нас хозяин… О!..",0,1279,0,0],["v","О боги! но зачем зову их?.. Разве",0,1280,0,1],["v","Я тронуть их когда-нибудь умела?..",0,1281,0,0],["v","Ну что ж, идем, бежим туда, в костер,",0,1282,0,0],["v","С ней умереть хочу… с моею Троей…",0,1283,0,0],["sp","<span class=\"ch\" data-ch=\"talfibiy\">Талфибий</span>"],["v","Не горе ли с ума ее свело?",0,1284,0,0],["v","Гей, взять ее без разговоров! Должен",0,1285,0,0],["v","Лаэртиад добычу получить.",0,1286,0,0],["scene","Явление четырнадцатое","s18",5,18],["sd","Те же, без <span class=\"ch\" data-ch=\"talfibiy\">Талфибия</span>. Все лица женщин обращаются на пожар."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["str","Строфа I"],["v","Ай, ай! Ой, ой! Ой, ой!",0,1287,0,0],["v","Отец, о Кронион! Фригийский притан!",0,1288,0,0],["v","О, разве не видишь, в какой позор",0,1289,0,0],["v","Дардана род низринут?",0,1290,2,1],["sp","Хор"],["v","Видит… А наша",0,1291,2,0],["v","Отчизна прекрасная гибнет…",0,1292,0,0],["v","Конец нашей Трое!..",0,1293,3,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["str","Антистрофа I"],["v","Ай, ай! Ой, ой! Ой, ой!",0,1294,0,0],["v","Гляди, Илион пылает,",0,1295,1,0],["v","Твердыни Пергама в огне. В огне",0,1296,0,0],["v","Стены, гордые стены…",0,1297,2,0],["sp","Хор"],["v","Троя, прости нам!",0,1298,1,0],["v","И дымом и кликом объяты",0,1300,0,1],["v","Гордые залы!..<a class=\"nr\" href=\"#n-k49\" data-n=\"k49\" aria-label=\"Примечание 49\">49</a>",0,1301,2,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","Строфа II Земля! Кормилица детей моих!.."],["sp","Хор"],["v","Ох! ох!",0,1302,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","О дети! вы слышите ль голос мой?",0,1303,0,0],["sp","Хор"],["v","Вопли твои пробудят мертвых…",0,1304,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ах, старые кости к земле ведет,",0,1305,0,0],["v","И руки по черной мои стучат…",0,1306,0,0],["sp","Хор"],["v","Колени склоняю и я за тобой,",0,1307,0,0],["v","И милых своих я прошу у земли,",0,1308,0,0],["v","Несчастного мужа.",0,1309,1,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Ведут, влекут нас…",0,1310,0,1],["sp","Хор"],["v","Вопит-то, вопит как…",0,1310,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Под кров господский.",0,1311,0,0],["sp","Хор"],["v","Из Илиона…",0,1312,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы, увы!",0,1312,0,0],["v","Приам, Приам мой, о ты, погибель,",0,1313,0,0],["v","О безмогильный, о одинокий,",0,1314,0,0],["v","Ты слышишь, слышишь…",0,1315,0,0],["sp","Хор"],["v","Убийство вежды тому смежило,",0,1315,0,0],["v","Кем царь убит наш благочестивый.",0,1316,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["sd","Антистрофа II О храмы божьи! О город мой!"],["sp","Хор"],["v","Ох! ох!",0,1317,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Вы сгибли от ярости пламенной.",0,1317,0,0],["sp","Хор"],["v","Имя, и то — не сгибнет ли ваше?",0,1318,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","От рухнувших башен клубится пар,",0,1319,0,0],["v","И дома за дымом нельзя узнать…",0,1320,0,1],["sp","Хор"],["v","Ах, скоро имя отчизны уйдет.",0,1321,0,0],["v","Дыхание смерти то здесь, то там.",0,1322,0,0],["v","А ты где, о город?",0,1323,0,0],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Чу, слышишь, слышишь?",0,1324,0,0],["sp","Хор"],["sd","Башен крушение."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","И дрожь и гулы…",0,1325,0,0],["sp","Хор"],["sd","Волной на город."],["sp","<span class=\"ch\" data-ch=\"gekuba\">Гекуба</span>"],["v","Увы, увы!",0,1326,0,0],["v","Как вся дрожу я. Несите, ноги,",0,1327,0,0],["v","Меня, рабыню, и на страданье.",0,1328,0,0],["v","О, как дрожу я…",0,1330,0,1],["sp","Хор"],["v","Несчастный город. Прости, торопят.",0,1331,0,0],["v","Туда, к ахейским ладьям иду я.",0,1332,0,0],["h1","Комментарий","comm"],["p","Трагедия была поставлена на Великих Дионисиях 415 г. до н. э. и занимала третье место в трилогии, в которую входили также трагедии «Александр» и «Паламед». Содержание первой из них составляло узнавание родителями выросшего среди пастухов Париса (оно произошло во время погребальных игр, устроенных в Трое в память о мнимо погибшем ребенке), второй — ложное обвинение и казнь Паламеда (см. примеч. к «Андромахе», ст. 293 — 300, и к «Елене», ст. 766 — 769). Поскольку действие всех трех трагедий происходило в Трое или в греческом лагере на Троянской равнине, охватывая историю Илиона от событий, предшествовавших войне, до ее окончания, и к тому же среди действующих лиц «Троянок» двое — Гекуба и Кассандра — принимали участие в действии «Александра», трилогия 415 г. представляла крайне редкий, если не единичный случай в творчестве Еврипида, когда три трагедии составляли связную трилогию, объединенную единством сюжета и художественного замысла. Впрочем, очевидная антивоенная направленность всех трех пьес снова лишила Еврипида в условиях подготовки Сицилийской экспедиции заслуженной награды: он удостоился только второго места, а победителем был признан второстепенный драматург Ксенокл."],["p","Текст печатается по рукописям Анненского, хранящимся в РГАЛИ: для ст. 10-32, 368-392, 411-430, 683-703, 722-742, 905-933 тексты беловые, для остальных — черновые."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"],["note","k48"],["note","k49"]],"n":{"k1":["Ст. 10. Муж парнасский","фокеец Эпей, строитель троянского коня."],"k2":["Ст. 28-31","Здесь и далее, изображая участь побежденной Трои, Еврипид находился под впечатлением расправы, которую афиняне учинили в 416 г. над городом Мелосом: за отказ подчиниться Афинам он был осажден афинским войском, и после капитуляции все захваченные мужчины были умерщвлены, а женщины и дети обращены в рабство."],"k3":["Ст. 39. …Злодейски дочь убита Поликсена…","Об участи Поликсены см. подробнее трагедию «Гекуба». Втихомолку — добавление переводчика."],"k4":["Ст. 71. А эллины глядели…","Еврипид здесь усиливает образ нечестивости ахейцев. Согласно недошедшей поэме «Разорение Илиона» (известна в позднем пересказе), ахейцы хотели побить Аякса (речь идет о младшем Аяксе из Локриды) камнями, но в последнюю минуту сжалились. Об этом же писал Алкей в недавно найденном Кельнском папирусе."],"k5":["Ст. 89-91. Лемнос","крупный остров, лежащий на половине пути от Троады до Халкидского полуострова; юго-западнее, ближе к Евбее, — остров Скирос; на восточной оконечности Евбеи — Каферейский мыс; Микон и рядом с ним Делос — острова из группы Кикладских. Принятые Анненским краткие формы названий островов (Лемн, Скир) в русской топонимике не прижились."],"k6":["Ст. 95. Не слеп ли меж людей…","О воздаянии, ожидающем разрушителей городов и храмов, ср.: Эсхил, «Агамемнон», ст. 341-344."],"k7":["Ст. 98-152","Монолог Гекубы, начинающийся в оригинале с мелодекламации в анапестах (ст. 98-121), переходит затем в монодию."],"k8":["Ст. 170. Кассандру, смотрите, на зов…","Мысль не закончена. В оригинале: «Кассандру не выпускайте наружу»."],"k9":["Ст. 187. На нивы Ахайи…","Недосмотр переводчика. В оригинале речь идет об Арголиде, а Ахайя — горная страна на севере Пелопоннеса, не имеющая прямого отношения к Аргосу и Микенам. Та же ошибка — в ст. 230."],"k10":["Ст. 205. Пирена","источник в Коринфе."],"k11":["Ст. 214. Край Пенея тучнополянный","Фессалия."],"k12":["Ст. 220-223. …О полях Гефеста близ Этны…","Речь идет о Сицилии, расположенной напротив Карфагена, основанного финикийцами. Комплименты Сици- лии в этой трагедии можно расценивать только как призыв к мирному урегулированию ожидаемого конфликта."],"k13":["Ст. 224 — 229. Есть и еще земля…","область в Южной Италии, на берегу Тарентинского залива, где в середине V в. афиняне основали в устье реки Кратиса колонию Фурии."],"k14":["Ст. 250. Рабыней спартанской невесты…","Клитемнестры."],"k15":["Ст. 268",", 270. Двусмысленные реплики Талфибия были хорошо понятны зрителям, знавшим содержание «Гекубы» и только что слышавшим слова Посейдона (ст. 39)."],"k16":["Ст. 292 сл","пропущены Анненским.<br>Корифей<br>Ты о себе узнала, госпожа, -<br>А мне чьей быть в Ахайе иль в Элладе?<br>(Перевод С. В Шервинского)"],"k17":["Ст. 310","Пропущено: «О Гименей царь!»"],"k18":["Ст. 315. Если ты, мать…","Маловразумительный перевод. Смысл оригинала: «Если ты, мать, оплакиваешь отца и отчизну, то я своим браком разожгу огонь…»"],"k19":["Ст. 355-373. Кассандра вспоминает о жертвоприношении Ифигении и предвещает убийство Агамемнона и месть Ореста. Его дворец я разорю…","Некоторое преувеличение: Клитемнестра оправдывала убийство Агамемнона его связью с Кассандрой, но это был скорее повод, чем причина ее решения."],"k20":["Ст. 356. Ведь если Локсий","бог… — Смысл перевода: «Если существует Локсий, то Агамемнон берет во мне жену, способную принести еще больше несчастья, чем Елена»."],"k21":["Ст. 382. …чтобы кровью… оросили.","Разумеется, кровью жертвенных животных."],"k22":["Ст. 384. Но затаим постыдное!","Скорее всего Кассандра намекает на измену Клитемнестры Агамемнону; как девушке ей не полагается касаться этой темы."],"k23":["Ст. 419. Мне наплевать.","Вульгаризм, не имеющий основания в тексте, где сказано: твои нападки я бросаю на ветер."],"k24":["Ст. 433-443","Краткое изложение содержания «Одиссеи». ..мясо… горько покажется Лаэртиаду. — Когда спутники Одиссея вопреки запрету убили священных коров из стада Гелиоса и стали их жарить, их мясо угрожающе мычало (см.: «Одиссея», XII, 395 сл.)."],"k25":["Ст. 483. Геркейского.","То есть около самого домашнего очага."],"k26":["Ст. 500. Подруга бога…","Неточность переводчика, так как Кассандра не отдалась Аполлону. В оригинале речь идет о том, что она приобщилась к богам, получив от Аполлона дар прорицания."],"k27":["Ст. 511-567","Хор поет о последних часах Трои — о деревянном коне, о песнях и плясках, которыми троянцы праздновали мнимый отъезд врагов. Источником этих описаний были послегомеровские поэмы «Малая Илиада» и «Разорение Илиона»."],"k28":["Ст. 595-602","В разных рукописях и, соответственно, в различных изданиях стихи эти распределяются между действующими лицами по-разному: ст. 595 сл. делят между Андромахой (или хором) и Гекубой; то же самое — в ст. 601 сл. Сплошного монолога Андромахи (ст. 595-600) и последующего — Гекубы — ни одно современное издание не дает."],"k29":["Ст. 611. …тебе ли видеть нас?","То есть в таком жалком состоянии."],"k30":["Ст. 632. Гляди, дитя…","Невразумительный перевод. В оригинале: «Глядеть на свет — не одно и то же, что умереть»."],"k31":["Ст. 679. …не горше смерти…","то есть гибели Поликсены."],"k32":["Ст. 799-819","Для прославления Афин Еврипид выбирает имя саламинского героя Теламона, участвовавшего в походе Геракла («сына Алкмены») против Трои. Причиной этого похода было очередное вероломство царя Лаомедонта; за то, что он обманул Аполлона и Посейдона (см. примеч. к «Андромахе», ст. 1009-1026), его дочь Гесиона была обречена в жертву морскому чудовищу. Лаомедонт пообещал в дар Гераклу своих чудесных коней, если он спасет его дочь; когда же Геракл убил чудовище, Лаомедонт отказался отдать ему обещанную награду, и разгневанный герой с помощью своих соратников разорил Трою. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 1009-1026.</b> По старинному преданию, Аполлон вместе с «царем морей» Посейдоном в течение года находились в услужении у троянского царя Лаомедонта, для которого они возвели мощные крепостные стены Трои. Однако Лаомедонт не заплатил им обещанной платы, чем в «Илиаде» и объясняется нена- висть Посейдона к троянцам (XXI, 441 — 460).</span><!--/xn-->"],"k33":["Ст. 820-839","Строфа обращена к Ганимеду; мысль продолжается и в следую- щей строфе, ст. 840-846."],"k34":["Ст. 852. …мужа избрала себе…","Богиня Зари Эос полюбила Тифона, брата Приама; от этого брака родился Мемнон, чьи подвиги и смерть описывались в поэме «Эфиопида», примыкавшей по содержанию к «Илиаде»."],"k35":["Ст. 886. …Иль разум наш…","Отражение философских взглядов Гераклита, согласно учению которого миром правит логос, и Анаксагора, у которого первичным принципом считался вечный разум. Отсюда — удивление Менелая, слышащего эту необычную молитву."],"k36":["Ст. 922. …То факела подобье роковое…","См. примеч. к «Андромахе», ст. 293-300. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 293-300. О, зачем Париса мать щадила….</b> Когда Гекуба, жена Приама, была беременна Парисом, ей приснилось, что она родила пылающую головню, и прорицатели растолковали этот сон таким образом, что сын Гекубы погубит Трою. Однако родители пожалели сына и, вместо того чтобы умертвить его, велели пастухам бросить младенца в горах. Парис уцелел, узнал о своем царском происхождении и был принят родителями.</span><!--/xn-->"],"k37":["Ст. 986. Амиклы","город в долине Еврота, южнее Спарты, где существовал древний культ Афродиты."],"k38":["Ст. 993. Аргос","здесь в значении «Пелопоннес»."],"k39":["Ст. 1001. …тогда еще не звезды?..","После смерти Кастор и его брат Полидевк были обращены в созвездие Близнецов."],"k40":["Ст. 1075 сл. Где двенадцать лун?","Речь идет о ритуальных пирогах, имевших форму луны и приносившихся в полнолуния ей в дар как богине (Селене)."],"k41":["Ст. 1100. Спартанцу","то есть Менелаю."],"k42":["Ст. 1107. …Отраду зеркал девичьих…","В подлиннике смысл совсем другой: пусть гибель постигнет Елену, когда она будет смотреться в зеркало."],"k43":["Ст. 1112. Питана","одно из укреплений города Спарты."],"k44":["Ст. 1127 сл. …которого прогнал Акаст…","По одному из вариантов мифа, на царство Пелея, во время отсутствия Ахилла, напал Акаст, царь фессалийского города Иолка."],"k45":["Ст. 1212 сл. Ты матери… украсить дай себя.","То есть дай Гекубе, матери твоего отца, обрядить тебя в отцовское добро, по праву тебе принадле- жащее."],"k46":["Ст. 1224 сл. …щит хитреца и труса","Одиссея. — Намек на присуждение Одиссею, в обход более храброго Аякса, доспехов погибшего Ахилла."],"k47":["Ст. 1246. Идите же…","Приказание, явно противоречащее словам Талфибия, готового взять погребение на себя. См; ст. 1147 сл., 1153."],"k48":["Ст. 1256-1259","Некоторые рукописи и издания отдают и эти стихи Корифею, для которого анапесты более свойственны, чем для Гекубы."],"k49":["Ст. 1287-1301","Симметрия строф в оригинале не вполне достоверна."]},"mainEnd":1779,"c":[{"id":"gekuba","name":"Гекуба","role":"Вдова Приама","intro":"Царица разрушенной Трои, ожидающая своей участи у шатров ахейцев.","arc":"В «Троянках» почти нет действия: Гекуба — центр, вокруг которого проходят одна за другой беды. Ей объявляют, кто кому достаётся; она видит безумную Кассандру, Андромаху, у которой отнимают сына; в споре с Еленой требует её смерти; наконец хоронит внука на щите Гектора и видит, как горит Троя.","st":[{"i":211,"p":12,"l":"Пролог · явление четвертое","t":"Плач","d":"Оплакивает Трою и свою судьбу.","c":"","k":false},{"i":317,"p":18,"l":"Пролог · Вступительная песнь хора","t":"Жребий","d":"Узнаёт, что её дочь Кассандра достанется Агамемнону, а она сама — Одиссею.","c":"","k":false},{"i":1136,"p":64,"l":"Действие второе · Второй музыкальный антракт","t":"Суд над Еленой","d":"Обличает Елену перед Менелаем и требует её смерти.","c":"","k":true},{"i":1467,"p":83,"l":"Действие третье · Третий музыкальный антракт","t":"Похороны внука","d":"Хоронит Астианакта на щите Гектора.","c":"Вершина скорби.","k":true},{"i":1662,"p":93,"l":"Исход · явление двенадцатое","t":"Гибель Трои","d":"Видит, как Троя сгорает, и уходит к кораблям.","c":"","k":false}],"gen":"Гекуба"},{"id":"kassandra","name":"Кассандра","role":"Дочь Приама, пророчица Аполлона","intro":"Пророчица, которой никто не верит.","arc":"Кассандра появляется в безумном восторге, с факелом, и поёт свадебный гимн себе — наложнице Агамемнона. Её пророчество превращает позор в торжество: её брак принесёт гибель Атридам.","st":[{"i":317,"p":18,"l":"Пролог · Вступительная песнь хора","t":"Свадебная песнь","d":"Ликует о своём «браке» и предсказывает гибель Агамемнона.","c":"","k":true}],"gen":"Кассандра"},{"id":"andromaha","name":"Андромаха","role":"Вдова Гектора","intro":"Вдова, у которой отнимают сына.","arc":"Андромаха узнаёт, что достанется сыну Ахилла, а её сына Астианакта сбросят со стены.","st":[{"i":674,"p":38,"l":"Действие первое · явление шестое","t":"Разлука с сыном","d":"Прощается с Астианактом, которого уводят на смерть.","c":"","k":true}],"gen":"Андромаха"},{"id":"elena","name":"Елена","role":"Жена Менелая","intro":"Виновница войны, защищающая себя перед мужем.","arc":"Елена блестяще оправдывается: во всём виновны боги, Афродита и Приам. Менелай обещает казнить её дома — но зритель знает, что этого не будет.","st":[{"i":1136,"p":64,"l":"Действие второе · Второй музыкальный антракт","t":"Самооправдание","d":"Защищается перед Менелаем, сваливая вину на богов.","c":"","k":true}],"gen":"Елена"},{"id":"menelay","name":"Менелай","role":"Царь Спарты","intro":"Обманутый муж, пришедший за Еленой.","arc":"Менелай обещает казнить Елену, но не может устоять перед её красотой.","st":[{"i":1136,"p":64,"l":"Действие второе · Второй музыкальный антракт","t":"Решение","d":"Выслушав обе стороны, обещает казнить Елену в Греции.","c":"","k":true}],"gen":"Менелай"},{"id":"talfibiy","name":"Талфибий","role":"Глашатай ахейцев","intro":"Вестник, исполняющий жестокие приказы и сочувствующий пленницам.","arc":"Талфибий — сочувствующий вестник, вынужденный объявлять страшные решения.","st":[{"i":317,"p":18,"l":"Пролог · Вступительная песнь хора","t":"Жребий пленниц","d":"Объявляет, кому достанутся троянки.","c":"","k":false},{"i":674,"p":38,"l":"Действие первое · явление шестое","t":"Приговор Астианакту","d":"Сообщает Андромахе, что сына сбросят со стены.","c":"","k":true},{"i":1402,"p":79,"l":"Действие третье · явление десятое","t":"Тело ребёнка","d":"Приносит тело Астианакта на щите Гектора.","c":"","k":false}]}]};
